-- 0000_baseline.sql — GENERATED by neon/port-baseline.mjs. Do not hand-edit.
-- Regenerate: npm run db:port. Requires Managed Auth deployed first
-- (neon_auth."user" must exist for the FK references below).

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- Session identity for triggers/guards (replaces auth.uid()).
CREATE OR REPLACE FUNCTION public.app_uid() RETURNS uuid
LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;

-- ── source: supabase/migrations/0001_org_membership.sql ──
-- Migration 0001: organizations, memberships, invitations (phase 03, plan 02)
-- D-01 owner-creates-org bootstrap; D-02 app-generates/human-sends invitations
-- (distinct org invites: no patient-specific columns); D-10 exactly one role per
-- (user, org) via unique(org_id, user_id); AUTH-02 access only via explicit
-- membership records; PRODUCT-MASTER-SPEC.md §13 relational model
-- Organization -> Membership -> User and the invitation object.
--
-- The five role strings in the check constraints are the PERMANENT canonical
-- vocabulary; src/lib/auth/roles.ts (plan 03-03) mirrors them verbatim. Do not
-- clip, rename or reorder without reading plan 03-03.
--
-- memberships(user_id) gets a standalone btree: the unique(org_id, user_id)
-- composite does not serve a user_id-leading filter and the RLS policy on
-- memberships filters by user_id (Pitfall 8).
-- invitations stores ONLY the SHA-256 digest of the invite token; the raw token
-- is never persisted, so a database read cannot mint redeemable invites.

create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  created_by uuid not null references neon_auth."user"(id),
  created_at timestamptz not null default now()
);

create table public.memberships (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  user_id uuid not null references neon_auth."user"(id) on delete cascade,
  role text not null check (
    role in ('provider_doctor', 'nurse', 'receptionist', 'patient', 'admin_owner')
  ),
  created_at timestamptz not null default now(),
  unique (org_id, user_id)
);

create index memberships_user_id_idx on public.memberships using btree (user_id);

create table public.invitations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  role text not null check (
    role in ('provider_doctor', 'nurse', 'receptionist', 'patient', 'admin_owner')
  ),
  token_digest text not null unique,
  short_code text unique,
  created_by uuid not null references neon_auth."user"(id),
  created_at timestamptz not null default now(),
  expires_at timestamptz,
  redeemed_at timestamptz,
  redeemed_by uuid references neon_auth."user"(id)
);


-- ── source: supabase/migrations/0002_rls.sql ──
-- Migration 0002: RLS policies + security-definer membership helper (phase 03, plan 02)
-- AUTH-02 explicit-membership access; AUTH-04 direct DB/API access without
-- membership context yields zero rows / rejected writes; AUTH-05 role-gated
-- mutations at the data layer; D-09/D-10/D-11 role vocabulary and capability
-- boundaries. The check-constraint role strings (migration 0001) are the shared
-- vocabulary mirroring src/lib/auth/roles.ts; the role->operation mapping here
-- mirrors the D-09 capability constants table authored in plan 03-03:
--   CAN_MANAGE_MEMBERSHIP  -> provider_doctor, admin_owner (members-list/invite surfaces)
--   CAN_RETRIEVE_AUDIT     -> admin_owner only (D-15, migration 0003)
-- supabase.com/docs/guides/database/postgres/row-level-security (Patterns 4):
-- definer helper wrapped (select ...) per policy (initPlan); every policy names
-- TO public; public.app_uid() guards written (select public.app_uid()) IS NOT NULL
-- AND ...; grants revoked then re-granted in the same migration (Pitfall 6 —
-- policies never revoke grants); helper is the ONLY membership reader inside
-- policies (Pitfall 7 recursion rule).
--
-- NO memberships update/delete policy and NO update/delete grant exists: member
-- removal flows exclusively through the migration-0004 security-definer
-- function `remove_membership` (created + pushed in plan 03-05 Task 1, called
-- via RPC by that plan's removeMemberAction). Deleting a membership any other
-- way is impossible: no grant, no policy — the write is denied at the grant
-- level before RLS is even consulted.
--
-- No UPDATE policy anywhere in this migration: organizations name changes are
-- deferred (no update grant below), and memberships/invitations mutations are
-- handled via grant shape and the redeem/removal definer functions — a Phase-3
-- capability that is deliberately not expressible through row policies.
-- UPDATE policies, where ever added, must carry both using and with check
-- (Pitfall 9).

create schema if not exists private;

create function private.user_org_role(p_org_id uuid) returns text
language plpgsql
security definer
set search_path = ''
stable
as $$
begin
  return (select role from public.memberships m
  where m.user_id = (select public.app_uid())
    and m.org_id = p_org_id);
end;
$$;

revoke execute on function private.user_org_role(uuid) from public;
revoke execute on function private.user_org_role(uuid) from public;
grant execute on function private.user_org_role(uuid) to public;
revoke all on schema private from public;
grant usage on schema private to public;

-- grants: revoke all, then re-grant only what each table needs (Pitfall 6)

revoke all on public.organizations from public;
grant select on public.organizations to public;
grant insert on public.organizations to public;

revoke all on public.memberships from public;
grant select on public.memberships to public;

revoke all on public.invitations from public;
grant select on public.invitations to public;
grant insert on public.invitations to public;

alter table public.organizations enable row level security;
alter table public.memberships enable row level security;
alter table public.invitations enable row level security;

-- organizations: member sees own org via the definer helper
create policy "select own organization"
on public.organizations
for select to public
using (
  (select private.user_org_role(id)) is not null
);

-- organizations insert: owner bootstrap only (D-01)
create policy "insert own organization"
on public.organizations
for insert to public
with check (
  (select public.app_uid()) is not null and
  created_by = (select public.app_uid())
);

-- memberships select: Revision r2 decision — user_id = public.app_uid() OR the
-- member-list surface reachable by CAN_MANAGE_MEMBERSHIP roles
-- (provider_doctor, admin_owner); unchanged across 03-02/03-03/03-05/03-06
create policy "select own or managed-membership"
on public.memberships
for select to public
using (
  (select public.app_uid()) is not null and
  (
    user_id = (select public.app_uid()) or
    (select private.user_org_role(org_id)) in ('admin_owner', 'provider_doctor')
  )
);

-- invitations select: invite-creation surface roles in own org
create policy "select invitations as invite-managers"
on public.invitations
for select to public
using (
  (select private.user_org_role(org_id)) in ('admin_owner', 'provider_doctor')
);

-- invitations insert: owner creates invites (D-01)
create policy "insert invitations as invite-managers"
on public.invitations
for insert to public
with check (
  (select private.user_org_role(org_id)) in ('admin_owner', 'provider_doctor')
);


-- ── source: supabase/migrations/0003_audit.sql ──
-- Migration 0003: audit_log + DB triggers (phase 03, plan 02)
-- D-14 audit is DB-trigger-based; D-15 retrieval is admin_owner-only;
-- AUTH-06 sensitive mutations produce audit entries. Later phases extend this
-- trigger pattern to their tables (03-RESEARCH.md Pattern 7).
--
-- Provenance survives in `diff`: UPDATEs record to_jsonb(old)/to_jsonb(new)
-- before/after, so created_at/created_by/redeemed_at are never lost (D-14/Claude
-- discretion clause). One security-definer trigger function per audited table;
-- the per-op branch keeps OLD/NEW referenced only where each row trigger
-- assigns them (OLD is unassigned on INSERT, NEW unassigned on DELETE).
-- audit_log grants: revoke all from public/public/public, grant
-- select to public only — writes happen ONLY inside the definer trigger
-- functions; there is no insert/update/delete grant and no policy admitting
-- product-user writes.

create table public.audit_log (
  id uuid primary key default gen_random_uuid(),
  actor uuid,
  action text not null,
  entity text not null,
  entity_id uuid,
  org_id uuid,
  diff jsonb,
  created_at timestamptz not null default now()
);

create index audit_log_org_created_idx on public.audit_log using btree (org_id, created_at);

create function private.audit_membership_change() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.user_id), tg_op, 'memberships', new.id, new.org_id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.user_id), tg_op, 'memberships', new.id, new.org_id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.user_id), tg_op, 'memberships', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create function private.audit_organizations_change() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'organizations', new.id, new.id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid()), tg_op, 'organizations', new.id, new.id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.created_by), tg_op, 'organizations', old.id, old.id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create function private.audit_invitations_change() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'invitations', new.id, new.org_id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'invitations', new.id, new.org_id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.created_by), tg_op, 'invitations', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create trigger audit_membership after insert or update or delete
on public.memberships for each row
execute function private.audit_membership_change();

create trigger audit_organizations after insert or update or delete
on public.organizations for each row
execute function private.audit_organizations_change();

create trigger audit_invitations after insert or update or delete
on public.invitations for each row
execute function private.audit_invitations_change();

revoke all on public.audit_log from public;
grant select on public.audit_log to public;

alter table public.audit_log enable row level security;

create policy "select audit_log as admin_owner"
on public.audit_log
for select to public
using (
  (select private.user_org_role(org_id)) = 'admin_owner'
);


-- ── source: supabase/migrations/0004_invite_redeem.sql ──
-- Migration 0004: redeem_invite + remove_membership security-definer functions
-- (phase 03, plan 05). AUTH-02 instant invite redemption; D-01..D-04 invite
-- onboarding; D-15-consistent owner-only delete authority.
--
-- digest() comes from pgcrypto (pre-installed in the extensions schema on the
-- local stack — extensions.digest qualified explicitly because both functions
-- run with set search_path = '').
--
-- redeem_invite is the ONLY membership-insert path for invitees (no direct
-- memberships insert grant exists since 03-02) and remove_membership is the
-- ONLY memberships delete path (no delete grant/policy). The 0003 audit
-- triggers fire inside both function bodies, producing the AUTH-06/D-14 audit
-- rows with no app write path.
--
-- No-leak discipline: an invalid, expired, redeemed, or deleted invitation
-- raises the SAME constant 'invite_invalid'; a caller whose own membership row
-- is missing in the target org and a cross-org target both raise the SAME
-- 'membership_operation_failed' — neither function reveals whether the org,
-- target row, or token existed.

create or replace function public.redeem_invite(p_raw_token text)
returns json
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select public.app_uid());
  v_digest text;
  v_invitation public.invitations%rowtype;
  v_org_name text;
begin
  if v_uid is null then
    raise exception 'invite_invalid';
  end if;

  v_digest := encode(public.digest(p_raw_token, 'sha256'), 'hex');

  select * into v_invitation
  from public.invitations
  where token_digest = v_digest
    and redeemed_at is null
    and (expires_at is null or expires_at > now());

  if not found then
    raise exception 'invite_invalid';
  end if;

  insert into public.memberships (org_id, user_id, role)
  values (v_invitation.org_id, v_uid, v_invitation.role);

  update public.invitations
  set redeemed_at = now(), redeemed_by = v_uid
  where id = v_invitation.id;

  select name into v_org_name
  from public.organizations
  where id = v_invitation.org_id;

  return json_build_object(
    'organization', v_org_name,
    'orgId', v_invitation.org_id,
    'role', v_invitation.role
  );
end;
$$;

create or replace function public.remove_membership(p_membership_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select public.app_uid());
  v_target public.memberships%rowtype;
  v_actor_role text;
  v_admin_count int;
begin
  select * into v_target
  from public.memberships
  where id = p_membership_id;

  if not found then
    raise exception 'membership_operation_failed';
  end if;

  select role into v_actor_role
  from public.memberships
  where org_id = v_target.org_id and user_id = v_uid;

  if not found then
    raise exception 'membership_operation_failed';
  end if;

  if v_actor_role <> 'admin_owner' then
    raise exception 'membership_forbidden';
  end if;

  if v_target.role = 'admin_owner' then
    select count(*) into v_admin_count
    from public.memberships
    where org_id = v_target.org_id and role = 'admin_owner';

    if v_admin_count <= 1 then
      raise exception 'membership_last_admin';
    end if;
  end if;

  delete from public.memberships where id = p_membership_id;
end;
$$;

create or replace function private.bootstrap_org_membership() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.memberships (org_id, user_id, role)
  values (new.id, new.created_by, 'admin_owner');
  return new;
end;
$$;

create trigger bootstrap_org_membership after insert on public.organizations
for each row execute function private.bootstrap_org_membership();

create or replace function public.preview_invite(p_raw_token text)
returns json
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_digest text;
  v_invitation public.invitations%rowtype;
  v_org_name text;
begin
  v_digest := encode(public.digest(p_raw_token, 'sha256'), 'hex');

  select * into v_invitation
  from public.invitations
  where token_digest = v_digest
    and redeemed_at is null
    and (expires_at is null or expires_at > now());

  if not found then
    return null;
  end if;

  select name into v_org_name
  from public.organizations
  where id = v_invitation.org_id;

  return json_build_object(
    'organization', v_org_name,
    'role', v_invitation.role
  );
end;
$$;

create or replace function public.list_org_members(p_org_id uuid)
returns json
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_role text;
  v_rows json;
begin
  select role into v_actor_role
  from public.memberships
  where org_id = p_org_id and user_id = (select public.app_uid());

  if not found or v_actor_role not in ('admin_owner', 'provider_doctor') then
    raise exception 'membership_operation_failed';
  end if;

  select json_agg(
    json_build_object(
      'id', m.id,
      'user_id', m.user_id,
      'role', m.role,
      'email', u.email,
      'created_at', m.created_at
    ) order by m.created_at
  )
  into v_rows
  from public.memberships m
  join neon_auth."user" u on u.id = m.user_id
  where m.org_id = p_org_id;

  return coalesce(v_rows, '[]'::json);
end;
$$;

revoke execute on function public.redeem_invite(text) from public;
revoke execute on function public.remove_membership(uuid) from public;
revoke execute on function public.preview_invite(text) from public;
revoke execute on function public.list_org_members(uuid) from public;
grant execute on function public.redeem_invite(text) to public;
grant execute on function public.remove_membership(uuid) to public;
grant execute on function public.preview_invite(text) to public;
grant execute on function public.list_org_members(uuid) to public;


-- ── source: supabase/migrations/0005_patients.sql ──
-- Migration 0005: patients table, trigger-owned MRN/timestamps, trgm search,
-- org-scoped RLS, patient-linked invitations, patient audit (phase 04).
-- D-01 patient record without an account; D-03 optional user_id; D-04 invite
-- auto-link; D-07 MRN assigned by trigger, never typed; D-08 sex M/F; D-09 the
-- five status strings are the PERMANENT vocabulary mirrored by
-- src/lib/patients/status.ts; D-13 default 'new'; D-21 ONLY the patients table
-- (+ the invitations.patient_id column + redeem_invite extension D-04 needs);
-- D-22 last_activity_at maintained by trigger; D-23 column set; PROV-01/03/04,
-- AUTH-02/04/05, PRODUCT-MASTER-SPEC.md §13.
--
-- Composes 0001 (table discipline), 0002 (definer helper REUSE — every policy
-- below calls private.user_org_role, never a second membership reader
-- [Pitfall 7]; grants revoke-then-regrant [Pitfall 6]; UPDATE carries BOTH
-- using and with check [Pitfall 9]), 0003 (audit trigger-per-table — 03-CONTEXT
-- D-14: every later clinical phase extends the same trigger pattern), 0004
-- (redeem_invite replaced additively, no-leak discipline byte-identical).
--
-- Trigger-owned columns: mrn_seq (per-org advisory-locked sequence — no
-- client-supplied value survives [D-07]), updated_at/last_activity_at
-- (a missed action-layer call site can never mean a stale timestamp
-- [D-22, 04-RESEARCH Pitfall 7]). App code must never write them.
--
-- NO delete policy and NO delete grant: a clinical record is not a product
-- delete action in Phase 4 (0004's "no grant, no policy" doctrine).
--
-- Cross-plan contract (04-05): supabase/seed.sql inserts its deterministic
-- fixtures under `set session_replication_role = replica` so fixed mrn_seq /
-- timestamps survive these triggers. That bypass belongs to the SEED only,
-- never to app code; pgTAP below still proves every client path is overwritten.

create extension if not exists pg_trgm;

create table public.patients (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  -- D-03 optional link; the clinical record SURVIVES account deletion, hence
  -- set null (never cascade).
  user_id uuid references neon_auth."user"(id) on delete set null,
  first_name text not null,
  last_name text not null,
  dob date not null,
  sex text not null check (sex in ('M', 'F')),
  phone text not null,
  status text not null default 'new'
    check (status in ('stable', 'follow_up', 'needs_review', 'critical', 'new')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  last_activity_at timestamptz not null default now(),
  -- D-07: assigned by private.assign_patient_mrn() (BEFORE INSERT). The 0
  -- default only satisfies NOT NULL before the trigger overwrites it.
  mrn_seq integer not null default 0,
  -- Stored generated display MRN; computed after the BEFORE trigger has set
  -- mrn_seq (asserted by pgTAP 0005 cases c/d — if that ever fails, flip to a
  -- trigger-maintained plain column, never to app-side generation).
  mrn text generated always as ('MRN-' || lpad(mrn_seq::text, 4, '0')) stored not null
);

-- D-17: ONE indexed text projection of name + MRN + phone + DOB for the
-- server-side search (04-RESEARCH Pattern 2). Generated columns may not
-- reference generated columns (Pitfall 4), so the MRN expression is inlined.
-- Expression constraints proved against the live engine: to_char is not
-- immutable here and lower() cannot resolve a collation inside a generated
-- column, so the date is composed from extract() parts (immutable, verified)
-- and CASE IS HANDLED BY ILIKE at query time — ilike already folds case, so
-- no lower() is needed anywhere in this projection.
alter table public.patients add column search_text text
  generated always as (
    first_name || ' ' || last_name || ' ' ||
    'MRN-' || lpad(mrn_seq::text, 4, '0') || ' ' ||
    phone || ' ' ||
    lpad(extract(year from dob)::int::text, 4, '0') || '-' ||
    lpad(extract(month from dob)::int::text, 2, '0') || '-' ||
    lpad(extract(day from dob)::int::text, 2, '0')
  ) stored;

create unique index patients_org_mrn_seq_uq on public.patients (org_id, mrn_seq);
create unique index patients_user_id_uq on public.patients (user_id) where user_id is not null;
-- D-11/D-20 sort key (+ stable id tiebreak) and the filter-tab predicate index.
create index patients_org_last_activity_idx on public.patients (org_id, last_activity_at desc, id desc);
create index patients_org_status_idx on public.patients (org_id, status);
create index patients_search_text_trgm_idx on public.patients using gin (search_text gin_trgm_ops);

-- D-07: per-org sequential MRN under an advisory lock. The max()+1 read is
-- serialized per org by pg_advisory_xact_lock, and the unique backstop index
-- makes a race impossible to miss rather than to ship.
create function private.assign_patient_mrn() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(2004, hashtext(new.org_id::text));
  select coalesce(max(mrn_seq), 0) + 1
    into new.mrn_seq
  from public.patients
  where org_id = new.org_id;
  return new;
end;
$$;

create trigger assign_patient_mrn before insert on public.patients
for each row
execute function private.assign_patient_mrn();

-- D-22: any row change IS activity. Timestamps are trigger-owned; actions and
-- clients never write them (04-RESEARCH Pitfall 7).
create function private.touch_patient_timestamps() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.updated_at := now();
    new.last_activity_at := now();
    return new;
  end if;
  new.updated_at := now();
  new.last_activity_at := now();
  return new;
end;
$$;

create trigger touch_patient_timestamps
before insert or update on public.patients
for each row
execute function private.touch_patient_timestamps();

-- D-04: an invite may carry a patient link. Integrity guard (an invite can
-- only ever link a patient OF ITS OWN ORG — defense on top of the FK) plus the
-- D-22 invite-sent bump, both in the same definer trigger.
alter table public.invitations
  add column patient_id uuid references public.patients(id);

create function private.invitation_patient_link() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
begin
  if new.patient_id is null then
    return new; -- plain org invite — D-04's addition is strictly additive
  end if;

  select org_id into v_org from public.patients where id = new.patient_id;
  if v_org is null then
    raise exception 'invite_patient_missing';
  end if;
  if v_org <> new.org_id then
    raise exception 'invite_patient_mismatch';
  end if;

  update public.patients
  set last_activity_at = now() -- D-22 invite-sent bump (touch trigger owns updated_at)
  where id = new.patient_id;

  return new;
end;
$$;

create trigger invitation_patient_link after insert on public.invitations
for each row
execute function private.invitation_patient_link();

-- D-03/D-04: create or replace, SAME signature/no-leak discipline as 0004,
-- plus the first-link-wins patient connect and an additive patientLinked key
-- (existing consumers of the JSON keep working unchanged).
create or replace function public.redeem_invite(p_raw_token text)
returns json
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select public.app_uid());
  v_digest text;
  v_invitation public.invitations%rowtype;
  v_org_name text;
begin
  if v_uid is null then
    raise exception 'invite_invalid';
  end if;

  v_digest := encode(public.digest(p_raw_token, 'sha256'), 'hex');

  select * into v_invitation
  from public.invitations
  where token_digest = v_digest
    and redeemed_at is null
    and (expires_at is null or expires_at > now());

  if not found then
    raise exception 'invite_invalid';
  end if;

  insert into public.memberships (org_id, user_id, role)
  values (v_invitation.org_id, v_uid, v_invitation.role);

  if v_invitation.patient_id is not null then
    -- First link wins — never steal an existing link (D-03/D-04).
    update public.patients
    set user_id = v_uid, last_activity_at = now()
    where id = v_invitation.patient_id
      and user_id is null;
  end if;

  update public.invitations
  set redeemed_at = now(), redeemed_by = v_uid
  where id = v_invitation.id;

  select name into v_org_name
  from public.organizations
  where id = v_invitation.org_id;

  return json_build_object(
    'organization', v_org_name,
    'orgId', v_invitation.org_id,
    'role', v_invitation.role,
    'patientLinked', (v_invitation.patient_id is not null)
  );
end;
$$;

-- RLS (D-23 org-scoped; AUTH-02/04). Grants first (Pitfall 6: policies never
-- revoke grants) — COLUMN-LEVEL lists are the hardening: user_id/org_id/mrn
-- columns are not updatable and (except the pgTAP overwrite proof) not
-- insertable by app clients; the link is minted only by redeem_invite.
alter table public.patients enable row level security;

revoke all on public.patients from public;
grant select on public.patients to public;
-- mrn_seq is granted ONLY so the client-overwrite proof (pgTAP 0005 case d)
-- can attempt to supply it — the trigger discards the value (D-07).
grant insert (org_id, first_name, last_name, dob, sex, phone, status, mrn_seq)
  on public.patients to public;
grant update (first_name, last_name, dob, sex, phone, status)
  on public.patients to public;
-- no delete grant, no update grant on org_id/user_id/mrn/mrn_seq/…

create policy "select patients as staff-or-self"
on public.patients
for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or user_id = (select public.app_uid())
);

create policy "insert patients as staff"
on public.patients
for insert to public
with check (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  and user_id is null -- link only via redeem_invite (D-03/D-04)
);

-- with check here pins the NEW row's org to the actor's org (Pitfall 6);
-- user_id immutability on UPDATE comes from the column-level grant above.
create policy "update patients as staff"
on public.patients
for update to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
)
with check (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

-- Audit — 03-CONTEXT D-14's trigger pattern extended to the phase's clinical
-- table, copy-structured from 0003's audit functions (same jsonb diff shape).
create function private.audit_patients_change() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.user_id), tg_op, 'patients', new.id, new.org_id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.user_id), tg_op, 'patients', new.id, new.org_id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.user_id), tg_op, 'patients', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create trigger audit_patients after insert or update or delete
on public.patients for each row
execute function private.audit_patients_change();


-- ── source: supabase/migrations/0006_visits.sql ──
-- Migration 0006: visits (the encounter table), org-scoped RLS, role-aware
-- clinical-content guard, trigger-owned provenance, patient activity bump,
-- audit (phase 07).
-- Binds PRODUCT-MASTER-SPEC.md §13 (Encounter/Visit in the relational chain),
-- §23 (provenance), §3.1/§12 (authorization enforced server-side), and the
-- VIS-01..03 requirements.
--
-- Composes the established patterns, copied not reinvented:
--   0003  audit trigger-per-table (before/after jsonb diff, entity name).
--   0005  trigger-owned provenance; private.user_org_role as the ONLY
--         membership reader; grants revoke-then-regrant; column-level grants
--         that keep org/patient/author columns out of app UPDATEs; no delete
--         policy and no delete grant (a clinical record is not a product
--         delete action); the activity-bump-on-change idiom.
--
-- ROLE LIMIT (VIS-03): Postgres grants are per DATABASE role, and every app
-- user is `public`, so a column-level grant cannot distinguish a
-- receptionist from a doctor. The clinical-content limit is therefore enforced
-- by a role-aware BEFORE trigger (`private.guard_visit_content`): a principal
-- whose org role lacks clinical authoring may create a visit and edit its
-- scheduling fields, but may not write or change reason/documentation/
-- follow-up. The server action re-checks the same capability, and the UI hides
-- the fields — three layers, one rule (§3.1/§12).
--
-- Trigger-owned: created_by/updated_by (from public.app_uid()), created_at/
-- updated_at. App code must never write them (0005 discipline).
--
-- `session_replication_role` is never set here — that bypass belongs to
-- supabase/seed.sql's deterministic fixtures only.

create table public.visits (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  -- The closed stage vocabulary, mirrored byte-for-byte by
  -- src/lib/visits/status.ts (0005's drift discipline).
  stage text not null default 'pre_visit'
    check (stage in ('pre_visit', 'during_visit', 'after_visit')),
  scheduled_at timestamptz not null,
  visit_type text,
  location text,
  -- Clinical content (CAN_AUTHOR_CLINICAL only, enforced by trigger below).
  reason text,
  documentation text,
  follow_up text,
  follow_up_at date,
  -- Provenance (§23): where the record came from and who touched it. A future
  -- AI-extracted visit must be distinguishable from a clinician one.
  source text not null default 'clinician'
    check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index visits_org_scheduled_idx on public.visits (org_id, scheduled_at desc, id desc);
create index visits_patient_scheduled_idx on public.visits (patient_id, scheduled_at desc, id desc);
create index visits_org_stage_idx on public.visits (org_id, stage);

-- Provenance ownership: authors and timestamps are trigger-set from the
-- verified session; a client-supplied value can never survive.
create function private.touch_visit_provenance() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(public.app_uid(), new.created_by);
    new.updated_by := coalesce(public.app_uid(), new.updated_by, new.created_by);
    new.created_at := now();
  else
    new.updated_by := coalesce(public.app_uid(), new.updated_by);
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger touch_visit_provenance
before insert or update on public.visits
for each row
execute function private.touch_visit_provenance();

-- Org integrity (the patient must belong to the visit's org — defence on top
-- of the FK, 0005's invite-link pattern) plus the role-aware clinical guard.
create function private.guard_visit_content() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
  v_role text;
  v_authors_clinical boolean;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then
    raise exception 'visit_patient_missing';
  end if;
  if v_patient_org <> new.org_id then
    raise exception 'visit_patient_mismatch';
  end if;

  v_role := private.user_org_role(new.org_id);
  -- CAN_AUTHOR_CLINICAL holders per src/lib/auth/capabilities.ts (D-09).
  v_authors_clinical := v_role = 'provider_doctor';

  if not v_authors_clinical then
    if tg_op = 'INSERT' then
      if new.reason is not null or new.documentation is not null
         or new.follow_up is not null or new.follow_up_at is not null then
        raise exception 'visit_clinical_forbidden';
      end if;
    else
      if new.reason is distinct from old.reason
         or new.documentation is distinct from old.documentation
         or new.follow_up is distinct from old.follow_up
         or new.follow_up_at is distinct from old.follow_up_at then
        raise exception 'visit_clinical_forbidden';
      end if;
    end if;
  end if;

  return new;
end;
$$;

create trigger guard_visit_content
before insert or update on public.visits
for each row
execute function private.guard_visit_content();

-- A visit IS activity on the patient's record (0005's D-22 idiom): creating or
-- changing one bumps last_activity_at so the folder workspace reflects it.
create function private.visit_patient_activity() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.patients
  set last_activity_at = now() -- touch_patient_timestamps owns updated_at
  where id = new.patient_id;
  return new;
end;
$$;

create trigger visit_patient_activity
after insert or update on public.visits
for each row
execute function private.visit_patient_activity();

-- RLS + grants (0005 shape). Column-level lists keep org_id/patient_id/authors
-- out of app UPDATEs; a visit is never reparented.
alter table public.visits enable row level security;

revoke all on public.visits from public;
grant select on public.visits to public;
grant insert (org_id, patient_id, stage, scheduled_at, visit_type, location, reason, documentation, follow_up, follow_up_at)
  on public.visits to public;
grant update (stage, scheduled_at, visit_type, location, reason, documentation, follow_up, follow_up_at)
  on public.visits to public;
-- no delete grant, no update grant on org_id/patient_id/source/created_by/…

create policy "select visits as staff"
on public.visits
for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

create policy "insert visits as staff"
on public.visits
for insert to public
with check (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

create policy "update visits as staff"
on public.visits
for update to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
)
with check (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

-- Audit — 0003's trigger pattern, entity 'visits'.
create function private.audit_visits_change() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'visits', new.id, new.org_id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'visits', new.id, new.org_id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'visits', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create trigger audit_visits after insert or update or delete
on public.visits for each row
execute function private.audit_visits_change();


-- ── source: supabase/migrations/0007_medications.sql ──
-- Migration 0007: medications + medication_events (the lifecycle history),
-- org-scoped RLS, trigger-owned provenance and status history, audit
-- (phase 08).
-- Binds PRODUCT-MASTER-SPEC.md §13 (Medications in the relational chain),
-- §23 (provenance), §19 Ph008 (start → active → change → pause/stop →
-- historical), and MED-01..03.
--
-- TWO TABLES, ONE STORY:
--   medications        the CURRENT state (structured dose/frequency/route,
--                      status, dates, provenance) — never a JSON blob.
--   medication_events  the HISTORY: one row per lifecycle transition, written
--                      by a trigger so state and trail can never drift
--                      (MED-02 projects this table; the current row is never
--                      the timeline source).
--
-- CDSS-READY, DECISION-FREE (MED-03/§27): dose is numeric + unit, frequency
-- and route are closed vocabularies mirrored in src/lib/medications/status.ts,
-- and `rxnorm_code` reserves the normalisation slot a later phase fills. There
-- is NO interaction, contraindication or dosing-decision logic anywhere.
--
-- Patterns composed (copied, not reinvented): 0003 audit triggers; 0005
-- trigger-owned provenance / private.user_org_role / grant discipline /
-- no-delete / activity bump; 0006 role-aware guard (CAN_AUTHOR_CLINICAL).
--
-- `session_replication_role` is never set here — that bypass stays in
-- supabase/seed.sql.

-- ── medications ────────────────────────────────────────────────────────────
create table public.medications (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  name text not null,
  -- Structured dose (§13/MED-03): amount + unit are separate, queryable facts.
  dose_amount numeric(10, 3),
  dose_unit text,
  -- Closed vocabularies, mirrored in TypeScript (drift-checked like 0005).
  frequency text check (frequency in ('once_daily', 'twice_daily', 'three_times_daily', 'four_times_daily', 'weekly', 'as_needed')),
  route text check (route in ('oral', 'topical', 'inhaled', 'injection', 'sublingual', 'rectal', 'ophthalmic', 'otic', 'nasal', 'other')),
  status text not null default 'active' check (status in ('active', 'paused', 'stopped')),
  started_at timestamptz not null default now(),
  paused_at timestamptz,
  stopped_at timestamptz,
  -- Normalisation slot for a later vocabulary phase; never guessed here.
  rxnorm_code text,
  source text not null default 'clinician'
    check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index medications_org_patient_idx on public.medications (org_id, patient_id, started_at desc, id desc);
create index medications_org_status_idx on public.medications (org_id, status);

-- ── medication_events (the history) ────────────────────────────────────────
create table public.medication_events (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  medication_id uuid not null references public.medications(id) on delete cascade,
  kind text not null check (kind in ('started', 'changed', 'paused', 'resumed', 'stopped')),
  at timestamptz not null default now(),
  -- Structured before/after snapshot (the 0003 diff shape) — never prose.
  detail jsonb,
  actor uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index medication_events_org_at_idx on public.medication_events (org_id, at desc, id desc);
create index medication_events_patient_at_idx on public.medication_events (patient_id, at desc, id desc);
create index medication_events_medication_idx on public.medication_events (medication_id, at);

-- Provenance ownership on the current row (0005 idiom).
create function private.touch_medication_provenance() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(public.app_uid(), new.created_by);
    new.updated_by := coalesce(public.app_uid(), new.updated_by, new.created_by);
    new.created_at := now();
  else
    new.updated_by := coalesce(public.app_uid(), new.updated_by);
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger touch_medication_provenance
before insert or update on public.medications
for each row
execute function private.touch_medication_provenance();

-- The history is DB-owned: an insert writes `started`; an update writes exactly
-- one event for what actually changed (`changed`, `paused`, `resumed`,
-- `stopped`). Because this fires in the SAME statement as the row write, the
-- current state and the trail are atomic by construction (MED-01/MED-02).
create function private.record_medication_event() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_kind text;
  v_detail jsonb;
begin
  if tg_op = 'INSERT' then
    insert into public.medication_events (org_id, patient_id, medication_id, kind, at, detail, actor)
    values (new.org_id, new.patient_id, new.id, 'started', new.started_at,
            jsonb_build_object('after', to_jsonb(new)), coalesce(public.app_uid(), new.created_by));
    return new;
  end if;

  if new.status is distinct from old.status then
    v_kind := case new.status
      when 'paused' then 'paused'
      when 'stopped' then 'stopped'
      when 'active' then 'resumed'
      else 'changed'
    end;
  elsif new.dose_amount is distinct from old.dose_amount
     or new.dose_unit is distinct from old.dose_unit
     or new.frequency is distinct from old.frequency
     or new.route is distinct from old.route
     or new.name is distinct from old.name
     or new.rxnorm_code is distinct from old.rxnorm_code then
    v_kind := 'changed';
  else
    return new; -- a provenance-only touch is not a clinical event
  end if;

  v_detail := jsonb_build_object('before',
    jsonb_build_object('name', old.name, 'dose_amount', old.dose_amount, 'dose_unit', old.dose_unit,
                       'frequency', old.frequency, 'route', old.route, 'status', old.status),
    'after',
    jsonb_build_object('name', new.name, 'dose_amount', new.dose_amount, 'dose_unit', new.dose_unit,
                       'frequency', new.frequency, 'route', new.route, 'status', new.status));

  insert into public.medication_events (org_id, patient_id, medication_id, kind, at, detail, actor)
  values (new.org_id, new.patient_id, new.id, v_kind, now(), v_detail,
          coalesce(public.app_uid(), new.updated_by));
  return new;
end;
$$;

create trigger record_medication_event
after insert or update on public.medications
for each row
execute function private.record_medication_event();

-- Org integrity + clinical-authoring guard (0006's pattern, shared rule).
create function private.guard_medication_content() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then
    raise exception 'medication_patient_missing';
  end if;
  if v_patient_org <> new.org_id then
    raise exception 'medication_patient_mismatch';
  end if;

  -- Only CAN_AUTHOR_CLINICAL holders (D-09: provider_doctor) may author.
  if coalesce(private.user_org_role(new.org_id), '') <> 'provider_doctor' then
    raise exception 'medication_clinical_forbidden';
  end if;

  return new;
end;
$$;

create trigger guard_medication_content
before insert or update on public.medications
for each row
execute function private.guard_medication_content();

-- Activity follows the patient (0005 D-22 idiom).
create function private.medication_patient_activity() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.patients set last_activity_at = now() where id = new.patient_id;
  return new;
end;
$$;

create trigger medication_patient_activity
after insert or update on public.medications
for each row
execute function private.medication_patient_activity();

-- ── RLS + grants ───────────────────────────────────────────────────────────
alter table public.medications enable row level security;

revoke all on public.medications from public;
grant select on public.medications to public;
grant insert (org_id, patient_id, name, dose_amount, dose_unit, frequency, route, started_at, rxnorm_code)
  on public.medications to public;
grant update (name, dose_amount, dose_unit, frequency, route, status, paused_at, stopped_at, rxnorm_code)
  on public.medications to public;
-- no delete grant; org_id/patient_id/source/created_by/… are never app-writable

create policy "select medications as staff"
on public.medications
for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

create policy "insert medications as staff"
on public.medications
for insert to public
with check (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

create policy "update medications as staff"
on public.medications
for update to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
)
with check (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

alter table public.medication_events enable row level security;

revoke all on public.medication_events from public;
-- SELECT only: the history is written EXCLUSIVELY by the definer trigger above.
grant select on public.medication_events to public;

create policy "select medication events as staff"
on public.medication_events
for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

-- ── audit (0003 pattern) ───────────────────────────────────────────────────
create function private.audit_medications_change() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'medications', new.id, new.org_id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'medications', new.id, new.org_id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'medications', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create trigger audit_medications after insert or update or delete
on public.medications for each row
execute function private.audit_medications_change();

create function private.audit_medication_events_change() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (new.actor, tg_op, 'medication_events', new.id, new.org_id, null);
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.actor), tg_op, 'medication_events', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create trigger audit_medication_events after insert or delete
on public.medication_events for each row
execute function private.audit_medication_events_change();


-- ── source: supabase/migrations/0008_labs_imaging.sql ──
-- Migration 0008: labs + imaging lifecycles, documents/media, provenance, RLS
-- (phase 09).
-- Binds PRODUCT-MASTER-SPEC.md §13 (Labs/Imaging/Documents in the relational
-- chain), §23 (provenance), §19 Ph009 ("lifecycles, provenance, document/media
-- relationships, and timeline projection"), and LAB-01..03.
--
-- Shape: an ORDER is the lifecycle (ordered → resulted | cancelled); a RESULT
-- is an immutable clinical fact (insert-only) that flips its order to
-- `resulted` in the same statement (trigger), so status can never drift from
-- the facts. Media lives in `documents` (metadata) with a private Storage
-- bucket; a result may link the document that carries its report/scan.
--
-- Patterns composed: 0003 audit; 0005 trigger-owned provenance /
-- private.user_org_role / column grants / no-delete / activity bump; 0006
-- authoring guard (CAN_AUTHOR_CLINICAL) + org integrity on every table.
--
-- `session_replication_role` is never set here (seed-only bypass).

-- ── documents (media metadata) ─────────────────────────────────────────────
create table public.documents (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  kind text not null check (kind in ('lab_report', 'imaging_report', 'prescription', 'referral', 'other')),
  storage_path text not null,
  filename text not null,
  mime_type text,
  size_bytes bigint check (size_bytes is null or size_bytes >= 0),
  source text not null default 'clinician' check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create unique index documents_storage_path_uq on public.documents (storage_path);
create index documents_org_patient_idx on public.documents (org_id, patient_id, created_at desc);

-- ── lab_orders / lab_results ───────────────────────────────────────────────
create table public.lab_orders (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  name text not null,
  ordered_at timestamptz not null default now(),
  status text not null default 'ordered' check (status in ('ordered', 'resulted', 'cancelled')),
  notes text,
  document_id uuid references public.documents(id) on delete set null,
  source text not null default 'clinician' check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index lab_orders_org_patient_idx on public.lab_orders (org_id, patient_id, ordered_at desc, id desc);
create index lab_orders_org_status_idx on public.lab_orders (org_id, status);

create table public.lab_results (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  order_id uuid not null references public.lab_orders(id) on delete cascade,
  -- Structured result (§13): a queryable analyte + numeric value + unit +
  -- reference range + a closed flag. Never prose.
  analyte text not null,
  value numeric(14, 4),
  unit text,
  reference_range text,
  flag text check (flag in ('normal', 'low', 'high', 'critical')),
  resulted_at timestamptz not null default now(),
  document_id uuid references public.documents(id) on delete set null,
  source text not null default 'clinician' check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index lab_results_org_patient_idx on public.lab_results (org_id, patient_id, resulted_at desc, id desc);
create index lab_results_order_idx on public.lab_results (order_id, resulted_at);

-- ── imaging_orders / imaging_results ───────────────────────────────────────
create table public.imaging_orders (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  modality text not null,
  body_site text,
  ordered_at timestamptz not null default now(),
  status text not null default 'ordered' check (status in ('ordered', 'resulted', 'cancelled')),
  notes text,
  source text not null default 'clinician' check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index imaging_orders_org_patient_idx on public.imaging_orders (org_id, patient_id, ordered_at desc, id desc);

create table public.imaging_results (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  order_id uuid not null references public.imaging_orders(id) on delete cascade,
  impression text not null,
  resulted_at timestamptz not null default now(),
  document_id uuid references public.documents(id) on delete set null,
  source text not null default 'clinician' check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index imaging_results_org_patient_idx on public.imaging_results (org_id, patient_id, resulted_at desc, id desc);
create index imaging_results_order_idx on public.imaging_results (order_id, resulted_at);

-- ── provenance touch (orders + documents) ──────────────────────────────────
create function private.touch_order_provenance() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(public.app_uid(), new.created_by);
    new.updated_by := coalesce(public.app_uid(), new.updated_by, new.created_by);
    new.created_at := now();
  else
    new.updated_by := coalesce(public.app_uid(), new.updated_by);
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger touch_lab_order_provenance before insert or update on public.lab_orders
for each row execute function private.touch_order_provenance();
create trigger touch_imaging_order_provenance before insert or update on public.imaging_orders
for each row execute function private.touch_order_provenance();

-- ── org integrity + authoring guard on orders ──────────────────────────────
create function private.guard_order_content() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then
    raise exception 'order_patient_missing';
  end if;
  if v_patient_org <> new.org_id then
    raise exception 'order_patient_mismatch';
  end if;
  if coalesce(private.user_org_role(new.org_id), '') <> 'provider_doctor' then
    raise exception 'order_clinical_forbidden';
  end if;
  return new;
end;
$$;

create trigger guard_lab_order before insert or update on public.lab_orders
for each row execute function private.guard_order_content();
create trigger guard_imaging_order before insert or update on public.imaging_orders
for each row execute function private.guard_order_content();

-- ── result integrity + the lifecycle flip ─────────────────────────────────
-- A result must belong to an order of the SAME patient/org, must not attach to
-- a cancelled order, must reference a document of the same patient when one is
-- given, and — atomically — marks the order `resulted`.
create function private.guard_and_apply_lab_result() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.lab_orders;
begin
  select * into v_order from public.lab_orders where id = new.order_id;
  if not found then raise exception 'lab_result_order_missing'; end if;
  if v_order.org_id <> new.org_id or v_order.patient_id <> new.patient_id then
    raise exception 'lab_result_order_mismatch';
  end if;
  if v_order.status = 'cancelled' then raise exception 'lab_result_order_cancelled'; end if;
  if new.document_id is not null then
    if not exists (select 1 from public.documents d
                   where d.id = new.document_id and d.org_id = new.org_id and d.patient_id = new.patient_id) then
      raise exception 'lab_result_document_mismatch';
    end if;
  end if;

  update public.lab_orders
  set status = 'resulted' -- touch_order_provenance owns updated_at
  where id = new.order_id and status <> 'resulted';

  return new;
end;
$$;

create trigger guard_lab_result before insert on public.lab_results
for each row execute function private.guard_and_apply_lab_result();

create function private.guard_and_apply_imaging_result() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.imaging_orders;
begin
  select * into v_order from public.imaging_orders where id = new.order_id;
  if not found then raise exception 'imaging_result_order_missing'; end if;
  if v_order.org_id <> new.org_id or v_order.patient_id <> new.patient_id then
    raise exception 'imaging_result_order_mismatch';
  end if;
  if v_order.status = 'cancelled' then raise exception 'imaging_result_order_cancelled'; end if;
  if new.document_id is not null then
    if not exists (select 1 from public.documents d
                   where d.id = new.document_id and d.org_id = new.org_id and d.patient_id = new.patient_id) then
      raise exception 'imaging_result_document_mismatch';
    end if;
  end if;

  update public.imaging_orders
  set status = 'resulted'
  where id = new.order_id and status <> 'resulted';

  return new;
end;
$$;

create trigger guard_imaging_result before insert on public.imaging_results
for each row execute function private.guard_and_apply_imaging_result();

-- ── activity follows the patient ───────────────────────────────────────────
create function private.clinical_patient_activity() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.patients set last_activity_at = now() where id = new.patient_id;
  return new;
end;
$$;

create trigger activity_lab_orders after insert or update on public.lab_orders
for each row execute function private.clinical_patient_activity();
create trigger activity_imaging_orders after insert or update on public.imaging_orders
for each row execute function private.clinical_patient_activity();
create trigger activity_lab_results after insert on public.lab_results
for each row execute function private.clinical_patient_activity();
create trigger activity_imaging_results after insert on public.imaging_results
for each row execute function private.clinical_patient_activity();
create trigger activity_documents after insert on public.documents
for each row execute function private.clinical_patient_activity();

-- ── RLS + grants ───────────────────────────────────────────────────────────
alter table public.documents enable row level security;
alter table public.lab_orders enable row level security;
alter table public.lab_results enable row level security;
alter table public.imaging_orders enable row level security;
alter table public.imaging_results enable row level security;

do $$
declare
  t text;
begin
  foreach t in array array['documents', 'lab_orders', 'lab_results', 'imaging_orders', 'imaging_results']
  loop
    execute format('revoke all on public.%I from public', t);
    execute format('grant select on public.%I to public', t);
  end loop;
end;
$$;

grant insert (org_id, patient_id, kind, storage_path, filename, mime_type, size_bytes) on public.documents to public;
grant insert (org_id, patient_id, name, ordered_at, notes) on public.lab_orders to public;
grant update (name, ordered_at, status, notes, document_id) on public.lab_orders to public;
grant insert (org_id, patient_id, order_id, analyte, value, unit, reference_range, flag, resulted_at, document_id) on public.lab_results to public;
grant insert (org_id, patient_id, modality, body_site, ordered_at, notes) on public.imaging_orders to public;
grant update (modality, body_site, ordered_at, status, notes) on public.imaging_orders to public;
grant insert (org_id, patient_id, order_id, impression, resulted_at, document_id) on public.imaging_results to public;
-- results are insert-only clinical facts: no update, no delete anywhere.

-- One policy shape per table, staff-scoped (private.user_org_role is the only
-- membership reader). Documents are staff-selectable (media follows its record).
do $$
declare
  t text;
begin
  foreach t in array array['documents', 'lab_orders', 'lab_results', 'imaging_orders', 'imaging_results']
  loop
    execute format($f$
      create policy "select %1$s as staff" on public.%1$I
      for select to public
      using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'))
    $f$, t);
    execute format($f$
      create policy "insert %1$s as staff" on public.%1$I
      for insert to public
      with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'))
    $f$, t);
  end loop;
end;
$$;

create policy "update lab_orders as staff" on public.lab_orders
for update to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'))
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'));

create policy "update imaging_orders as staff" on public.imaging_orders
for update to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'))
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'));

-- ── Storage: a private bucket, org-scoped object policies ─────────────────
-- Object names follow `<org_id>/<patient_id>/<uuid>`; the policies read the
-- org from the path and reuse the SAME membership helper as the tables, so
-- media access and record access can never disagree. Upload UI is a later
-- phase; this makes the bucket safe the moment anything writes to it.
-- NEON-PORT: dropped storage bucket seed.


-- NEON-PORT: dropped Supabase storage policy (Neon Object Storage `uploads` bucket; enforced in app).


-- NEON-PORT: dropped Supabase storage policy (Neon Object Storage `uploads` bucket; enforced in app).


-- ── audit (0003 pattern) ───────────────────────────────────────────────────
do $$
declare
  t text;
  fn text;
begin
  foreach t in array array['documents', 'lab_orders', 'lab_results', 'imaging_orders', 'imaging_results']
  loop
    fn := format('audit_%s_change', t);
    execute format($f$
      create function private.%1$I() returns trigger
      language plpgsql security definer set search_path = ''
      as $body$
      begin
        if tg_op = 'INSERT' then
          insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
          values (coalesce(public.app_uid(), new.created_by), tg_op, %2$L, new.id, new.org_id, null);
          return new;
        elsif tg_op = 'UPDATE' then
          insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
          values (coalesce(public.app_uid(), new.updated_by), tg_op, %2$L, new.id, new.org_id,
                  jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
          return new;
        else
          insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
          values (coalesce(public.app_uid(), old.created_by), tg_op, %2$L, old.id, old.org_id,
                  jsonb_build_object('before', to_jsonb(old)));
          return old;
        end if;
      end;
      $body$;
    $f$, fn, t);

    execute format(
      'create trigger audit_%1$s after insert or update or delete on public.%1$I for each row execute function private.%2$I()',
      t, fn
    );
  end loop;
end;
$$;


-- ── source: supabase/migrations/0009_allergies_genetics.sql ──
-- Migration 0009: allergies + genetics with strong provenance and DATA-LAYER
-- role visibility for sensitive categories (phase 10).
-- Binds PRODUCT-MASTER-SPEC.md §13/§23, §12 (authorization enforced by the
-- database, not the UI), and ALG-01..03.
--
-- VISIBILITY (the phase's core requirement, ALG-03):
--   allergies  → all four staff roles. Allergy safety is a bedside fact; a
--                receptionist must never be able to hide it from a clinician.
--   genetics   → `provider_doctor` + `admin_owner` ONLY. A sensitive category;
--                the restriction lives in the SELECT policy, mirrored by
--                `CAN_VIEW_GENETICS` in src/lib/auth/capabilities.ts so the
--                UI shows a truthful denial instead of an empty list.
-- Writes (insert/update) on BOTH tables require `provider_doctor`
-- (CAN_AUTHOR_CLINICAL), enforced in the policy AND a definer guard trigger.
--
-- `verification` is a real column (`clinician-verified` | `ai-extracted`) so an
-- AI-extracted allergy/finding can never render as clinician-verified (§23);
-- manual entry defaults to clinician-verified, and Phase 12's OCR sets the
-- other value explicitly.
--
-- Patterns composed: 0003 audit; 0005 provenance/private.user_org_role/
-- column grants/no-delete/activity bump; 0006/0008 authoring guard + org
-- integrity. `session_replication_role` is never set here.

create table public.allergies (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  allergen text not null,
  reaction text,
  severity text check (severity in ('mild', 'moderate', 'severe', 'anaphylaxis')),
  status text not null default 'active' check (status in ('active', 'resolved')),
  noted_at timestamptz not null default now(),
  notes text,
  source text not null default 'clinician' check (source in ('clinician', 'ai-extracted', 'imported')),
  verification text not null default 'clinician-verified'
    check (verification in ('clinician-verified', 'ai-extracted')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index allergies_org_patient_idx on public.allergies (org_id, patient_id, noted_at desc, id desc);
create index allergies_org_status_idx on public.allergies (org_id, status);

create table public.genetics (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  kind text not null check (kind in ('variant', 'pharmacogenomic', 'hereditary-condition', 'other')),
  gene text,
  variant text,
  interpretation text,
  significance text check (significance in ('pathogenic', 'likely_pathogenic', 'uncertain', 'likely_benign', 'benign')),
  reported_at timestamptz not null default now(),
  -- The report document (0008 documents table); optional.
  document_id uuid references public.documents(id) on delete set null,
  source text not null default 'clinician' check (source in ('clinician', 'ai-extracted', 'imported')),
  verification text not null default 'clinician-verified'
    check (verification in ('clinician-verified', 'ai-extracted')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index genetics_org_patient_idx on public.genetics (org_id, patient_id, reported_at desc, id desc);

-- Provenance ownership (both tables).
create function private.touch_clinical_provenance() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(public.app_uid(), new.created_by);
    new.updated_by := coalesce(public.app_uid(), new.updated_by, new.created_by);
    new.created_at := now();
  else
    new.updated_by := coalesce(public.app_uid(), new.updated_by);
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create trigger touch_allergies_provenance before insert or update on public.allergies
for each row execute function private.touch_clinical_provenance();
create trigger touch_genetics_provenance before insert or update on public.genetics
for each row execute function private.touch_clinical_provenance();

-- Org integrity + authoring guard. A genetics row's optional document must
-- belong to the same patient/org (the 0008 relationship, integrity-checked).
create function private.guard_allergy_content() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then raise exception 'allergy_patient_missing'; end if;
  if v_patient_org <> new.org_id then raise exception 'allergy_patient_mismatch'; end if;
  if coalesce(private.user_org_role(new.org_id), '') <> 'provider_doctor' then
    raise exception 'allergy_clinical_forbidden';
  end if;
  return new;
end;
$$;

create trigger guard_allergy_content before insert or update on public.allergies
for each row execute function private.guard_allergy_content();

create function private.guard_genetic_content() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then raise exception 'genetic_patient_missing'; end if;
  if v_patient_org <> new.org_id then raise exception 'genetic_patient_mismatch'; end if;
  if coalesce(private.user_org_role(new.org_id), '') <> 'provider_doctor' then
    raise exception 'genetic_clinical_forbidden';
  end if;
  if new.document_id is not null then
    if not exists (select 1 from public.documents d
                   where d.id = new.document_id and d.org_id = new.org_id and d.patient_id = new.patient_id) then
      raise exception 'genetic_document_mismatch';
    end if;
  end if;
  return new;
end;
$$;

create trigger guard_genetic_content before insert or update on public.genetics
for each row execute function private.guard_genetic_content();

-- Activity follows the patient.
create trigger activity_allergies after insert or update on public.allergies
for each row execute function private.clinical_patient_activity();
create trigger activity_genetics after insert or update on public.genetics
for each row execute function private.clinical_patient_activity();

-- RLS + grants.
alter table public.allergies enable row level security;
alter table public.genetics enable row level security;

revoke all on public.allergies from public;
grant select on public.allergies to public;
grant insert (org_id, patient_id, allergen, reaction, severity, status, noted_at, notes) on public.allergies to public;
grant update (allergen, reaction, severity, status, noted_at, notes) on public.allergies to public;

revoke all on public.genetics from public;
grant select on public.genetics to public;
grant insert (org_id, patient_id, kind, gene, variant, interpretation, significance, reported_at, document_id) on public.genetics to public;
grant update (kind, gene, variant, interpretation, significance, reported_at, document_id) on public.genetics to public;

-- SELECT: allergies to all staff…
create policy "select allergies as staff"
on public.allergies for select to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'));

-- …genetics ONLY to the authorized sensitive-category roles (ALG-03).
create policy "select genetics as authorized clinicians"
on public.genetics for select to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'admin_owner'));

-- Writes: provider_doctor only, in both policies and the guards above.
create policy "insert allergies as author"
on public.allergies for insert to public
with check ((select private.user_org_role(org_id)) = 'provider_doctor');
create policy "update allergies as author"
on public.allergies for update to public
using ((select private.user_org_role(org_id)) = 'provider_doctor')
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

create policy "insert genetics as author"
on public.genetics for insert to public
with check ((select private.user_org_role(org_id)) = 'provider_doctor');
create policy "update genetics as author"
on public.genetics for update to public
using ((select private.user_org_role(org_id)) = 'provider_doctor')
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

-- Audit (0003 pattern) for both tables.
create function private.audit_allergies_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'allergies', new.id, new.org_id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'allergies', new.id, new.org_id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'allergies', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create trigger audit_allergies after insert or update or delete on public.allergies
for each row execute function private.audit_allergies_change();

create function private.audit_genetics_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'genetics', new.id, new.org_id, null);
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'genetics', new.id, new.org_id,
            jsonb_build_object('before', to_jsonb(old), 'after', to_jsonb(new)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'genetics', old.id, old.org_id,
            jsonb_build_object('before', to_jsonb(old)));
    return old;
  end if;
end;
$$;

create trigger audit_genetics after insert or update or delete on public.genetics
for each row execute function private.audit_genetics_change();


-- ── source: supabase/migrations/0010_ai_insights.sql ──
-- Migration 0010: AI insights substrate with provenance and human review
-- (phase 11). Binds PRODUCT-MASTER-SPEC.md §10 (AI principles), §23
-- (provenance), §12 (authorization enforced by the database), and
-- AI-01/02/03.
--
-- The phase's core requirement (AI-02): a stored insight can never render as
-- clinical truth. It carries `provenance` (system-derived | ai-generated),
-- defaults to `verification = 'ai-extracted'` so it is distinguishable from
-- clinician-verified data (§23), and exposes a `review_state` lifecycle
-- (pending | dismissed | accepted) with an attributed reviewer. Accepting an
-- insight is a clinician's decision ABOUT an observation — it flips
-- `verification` to clinician-verified and records who did it; dismissing is
-- also a decision and is kept, audited, never deleted.
--
-- AI-03: the table stores observations only. There is no column that could
-- hold a diagnosis or a prescribing decision, and no policy lets anything but
-- an in-session provider_doctor write content.
--
-- Writes: INSERT provider_doctor only (the in-session generator); UPDATE
-- provider_doctor + nurse, restricted by trigger to the review columns —
-- content is immutable after insert. No DELETE: the audit trail is the point.
-- SELECT: all four staff roles (assistive surface, org-scoped). Patients never
-- see insights.
--
-- Patterns composed: 0003 audit; 0005 provenance/user_org_role/column
-- grants/no-delete; 0009 role checks + audit trigger shape.
-- `session_replication_role` is never set here.

create table public.ai_insights (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  -- Closed vocabulary (mirror: src/lib/ai/status.ts).
  kind text not null check (kind in ('change', 'summary', 'attention', 'trend', 'documentation-gap')),
  title text not null,
  body text not null,
  -- Structured references to the REAL source rows this insight was derived
  -- from ({table, id, label} objects). An insight without evidence is not
  -- allowed to exist: the check requires at least one entry.
  evidence jsonb not null check (jsonb_typeof(evidence) = 'array' and jsonb_array_length(evidence) > 0),
  -- The period the insight covers ({from, to} ISO strings); null for
  -- point-in-time findings.
  "window" jsonb check ("window" is null or (jsonb_typeof("window") = 'object'
    and "window" ? 'from' and "window" ? 'to')),
  provenance text not null default 'system-derived'
    check (provenance in ('system-derived', 'ai-generated')),
  -- §23: AI output defaults to ai-extracted so it can never render
  -- indistinguishable from clinician-verified data.
  verification text not null default 'ai-extracted'
    check (verification in ('ai-extracted', 'clinician-verified')),
  review_state text not null default 'pending'
    check (review_state in ('pending', 'dismissed', 'accepted')),
  reviewed_by uuid references neon_auth."user"(id) on delete set null,
  reviewed_at timestamptz,
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index ai_insights_org_patient_idx
  on public.ai_insights (org_id, patient_id, created_at desc, id desc);
create index ai_insights_org_review_idx
  on public.ai_insights (org_id, patient_id, review_state);

-- Provenance ownership (0009 touch pattern).
create trigger touch_ai_insights_provenance before insert or update on public.ai_insights
for each row execute function private.touch_clinical_provenance();

-- Insert guard: same org as the patient, and only provider_doctor writes
-- insight content (the in-session generator).
create function private.guard_ai_insight_insert() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then raise exception 'ai_insight_patient_missing'; end if;
  if v_patient_org <> new.org_id then raise exception 'ai_insight_patient_mismatch'; end if;
  if coalesce(private.user_org_role(new.org_id), '') <> 'provider_doctor' then
    raise exception 'ai_insight_generate_forbidden';
  end if;
  -- A freshly generated insight starts life unreviewed, AI-extracted.
  new.verification := 'ai-extracted';
  new.review_state := 'pending';
  new.reviewed_by := null;
  new.reviewed_at := null;
  return new;
end;
$$;

create trigger guard_ai_insight_insert before insert on public.ai_insights
for each row execute function private.guard_ai_insight_insert();

-- Review guard: the ONLY mutable surface is the review lifecycle. Content
-- columns are immutable after insert, a reviewed insight is final (no
-- re-review), and the reviewer identity + timestamp are taken from the
-- public session — never from the client payload.
create function private.guard_ai_insight_review() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role text := coalesce(private.user_org_role(new.org_id), '');
begin
  if v_role not in ('provider_doctor', 'nurse') then
    raise exception 'ai_insight_review_forbidden';
  end if;

  -- Content immutability (§10: never silently transform AI output).
  if new.kind <> old.kind
    or new.title <> old.title
    or new.body <> old.body
    or new.evidence is distinct from old.evidence
    or new."window" is distinct from old."window"
    or new.provenance <> old.provenance
    or new.patient_id <> old.patient_id
    or new.org_id <> old.org_id
  then
    raise exception 'ai_insight_content_immutable';
  end if;

  -- Review is a one-way transition out of pending.
  if old.review_state <> 'pending' then
    raise exception 'ai_insight_review_final';
  end if;
  if new.review_state not in ('dismissed', 'accepted') then
    raise exception 'ai_insight_review_invalid';
  end if;

  -- Server-side attribution.
  new.reviewed_by := public.app_uid();
  new.reviewed_at := now();
  -- Accepting means a clinician verified the observation; a dismissal does not.
  if new.review_state = 'accepted' then
    new.verification := 'clinician-verified';
  else
    new.verification := 'ai-extracted';
  end if;
  return new;
end;
$$;

create trigger guard_ai_insight_review before update on public.ai_insights
for each row execute function private.guard_ai_insight_review();

-- RLS + grants.
alter table public.ai_insights enable row level security;

revoke all on public.ai_insights from public;
grant select on public.ai_insights to public;
grant insert (org_id, patient_id, kind, title, body, evidence, "window", provenance)
  on public.ai_insights to public;
grant update (review_state, verification, reviewed_by, reviewed_at)
  on public.ai_insights to public;
-- No DELETE grant, no DELETE policy: reviews are never erased.

-- SELECT: all four staff roles in the org (assistive surface).
create policy "select ai insights as staff"
on public.ai_insights for select to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'));

-- INSERT: provider_doctor only (the generator runs in-session).
create policy "insert ai insights as author"
on public.ai_insights for insert to public
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

-- UPDATE: doctor + nurse, and the trigger narrows it to the review columns.
create policy "review ai insights as clinician"
on public.ai_insights for update to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'))
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'));

-- Audit (0003 pattern): generation, review decisions AND the housekeeping
-- supersede are attributable. A superseded row is always an unreviewed
-- generated observation — a review decision is never erased (no DELETE grant
-- exists; the RPC below deletes pending rows only).
create function private.audit_ai_insights_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'ai_insights', new.id, new.org_id,
            jsonb_build_object('kind', new.kind, 'title', new.title));
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'ai_insights', new.id, new.org_id,
            jsonb_build_object(
              'review_state', jsonb_build_object('before', old.review_state, 'after', new.review_state),
              'reviewed_by', new.reviewed_by));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'ai_insights', old.id, old.org_id,
            jsonb_build_object('kind', old.kind, 'title', old.title, 'review_state', old.review_state));
    return old;
  end if;
end;
$$;

create trigger audit_ai_insights after insert or update or delete on public.ai_insights
for each row execute function private.audit_ai_insights_change();

-- Regeneration housekeeping: drop the patient's still-PENDING insights (never
-- the reviewed ones) so a regenerate replaces rather than accumulates. The
-- definer path re-checks the caller is provider_doctor in the patient's org —
-- the database still decides, the RPC only narrows the delete to pending rows.
create function public.supersede_pending_ai_insights(p_patient_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
begin
  select org_id into v_org from public.patients where id = p_patient_id;
  if v_org is null then raise exception 'ai_insight_patient_missing'; end if;
  if coalesce(private.user_org_role(v_org), '') <> 'provider_doctor' then
    raise exception 'ai_insight_supersede_forbidden';
  end if;
  delete from public.ai_insights
  where patient_id = p_patient_id and org_id = v_org and review_state = 'pending';
end;
$$;

revoke all on function public.supersede_pending_ai_insights(uuid) from public;
grant execute on function public.supersede_pending_ai_insights(uuid) to public;


-- ── source: supabase/migrations/0011_ocr_extractions.sql ──
-- Migration 0011: prescription extraction substrate (phase 12).
-- Binds PRODUCT-MASTER-SPEC.md §11 (prescription OCR / document
-- intelligence), §13 (relational model), §23 (provenance) and OCR-01..04.
--
-- The pipeline (§11): image → preprocessing → extraction → structured
-- extraction → normalization → confidence analysis → CLINICIAN VERIFICATION →
-- persistence → timeline projection. This table is the work item that carries
-- the job through that pipeline. It is NOT clinical truth: a row in
-- `awaiting_extraction`/`extracted` has produced nothing authoritative, and
-- `verification` defaults to `ai-extracted` so no pipeline output can ever
-- render as clinician-verified data (§23). The medication row 12-03 persists
-- from a CONFIRMED set of fields is the only authoritative output, and it
-- carries source='ai-extracted' so its origin stays visible.
--
-- Writes: provider_doctor only (the ingestion clinician). SELECT: the four
-- staff roles — an extraction in flight is team work, like a lab order. No
-- DELETE: a rejected extraction is a recorded decision, not an erased one.
--
-- Patterns composed: 0003 audit; 0005 provenance/user_org_role/column
-- grants/no-delete; 0008 documents FK + integrity pattern; 0010 session
-- attribution. `session_replication_role` is never set here.

create table public.ocr_extractions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  -- The uploaded prescription image (0008 documents, kind='prescription').
  document_id uuid not null references public.documents(id) on delete restrict,
  -- The pipeline's position: awaiting_extraction → extracted → verified,
  -- or rejected (a recorded decision, kept).
  status text not null default 'awaiting_extraction'
    check (status in ('awaiting_extraction', 'extracted', 'verified', 'rejected')),
  -- The extraction result: { provider, fields: [{key, value, confidence,
  -- candidates[]}] }. Zod-validated at the app boundary (12-02) before any
  -- write; the check here guarantees the envelope shape at the data layer.
  payload jsonb check (payload is null or (jsonb_typeof(payload) = 'object'
    and payload ? 'fields' and jsonb_typeof(payload -> 'fields') = 'array')),
  provider text,
  -- Rejection reason (why this extraction was not usable).
  rejection_reason text,
  -- Provenance (§23) + verification attribution.
  source text not null default 'ai-extracted'
    check (source in ('clinician', 'ai-extracted', 'imported')),
  verification text not null default 'ai-extracted'
    check (verification in ('clinician-verified', 'ai-extracted')),
  verified_by uuid references neon_auth."user"(id) on delete set null,
  verified_at timestamptz,
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index ocr_extractions_org_patient_idx
  on public.ocr_extractions (org_id, patient_id, created_at desc, id desc);
create index ocr_extractions_org_status_idx
  on public.ocr_extractions (org_id, patient_id, status);

-- Provenance ownership (0009 touch pattern).
create trigger touch_ocr_extractions_provenance before insert or update on public.ocr_extractions
for each row execute function private.touch_clinical_provenance();

-- Integrity + authoring guard: the document must belong to the same
-- patient/org, and only provider_doctor runs the pipeline. Status transitions
-- are validated here too, so a client cannot skip a stage or self-verify.
create function private.guard_ocr_extraction() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role text := coalesce(private.user_org_role(new.org_id), '');
  v_document record;
  v_patient_org uuid;
begin
  if v_role <> 'provider_doctor' then
    raise exception 'ocr_extraction_forbidden';
  end if;

  if tg_op = 'INSERT' then
    new.status := 'awaiting_extraction';
    new.verification := 'ai-extracted';
    new.verified_by := null;
    new.verified_at := null;
    new.rejection_reason := null;
  else
    -- Content immutability: which image a job reads never changes after
    -- creation — a different prescription is a different job.
    if new.document_id <> old.document_id
      or new.patient_id <> old.patient_id
      or new.org_id <> old.org_id
    then
      raise exception 'ocr_extraction_target_immutable';
    end if;

    -- Status transition table.
    if old.status = 'rejected' then
      raise exception 'ocr_extraction_rejected_final';
    elsif old.status = 'verified' then
      raise exception 'ocr_extraction_verified_final';
    elsif old.status = 'awaiting_extraction' and new.status not in ('extracted', 'rejected') then
      raise exception 'ocr_extraction_bad_transition';
    elsif old.status = 'extracted' and new.status not in ('verified', 'rejected') then
      raise exception 'ocr_extraction_bad_transition';
    end if;

    -- A verified/rejected row is attributable to the session, never the
    -- client payload; a verified extraction carries a payload.
    if new.status in ('verified', 'rejected') then
      new.verified_by := public.app_uid();
      new.verified_at := now();
      new.verification := case when new.status = 'verified' then 'clinician-verified' else 'ai-extracted' end;
    else
      new.verified_by := null;
      new.verified_at := null;
    end if;
    if new.status = 'rejected' and coalesce(new.rejection_reason, '') = '' then
      raise exception 'ocr_extraction_reason_required';
    end if;
  end if;

  -- The document must exist in the same patient/org scope (the 0008
  -- relationship, integrity-checked).
  select id, org_id, patient_id into v_document
  from public.documents where id = new.document_id;
  if v_document.id is null then
    raise exception 'ocr_extraction_document_missing';
  end if;
  if v_document.org_id <> new.org_id or v_document.patient_id <> new.patient_id then
    raise exception 'ocr_extraction_document_mismatch';
  end if;

  -- Patient/org integrity (0005 pattern).
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then
    raise exception 'ocr_extraction_patient_missing';
  end if;
  if v_patient_org <> new.org_id then
    raise exception 'ocr_extraction_patient_mismatch';
  end if;

  return new;
end;
$$;

create trigger guard_ocr_extraction before insert or update on public.ocr_extractions
for each row execute function private.guard_ocr_extraction();

-- ── The §23 provenance pair on medications (Phase 12) ─────────────────────
-- 0007 gave medications a `source` column but no `verification` half of the
-- §10 pair ("AI-extracted" vs "verified by clinician"), so a confirmed
-- extraction could not record that a clinician checked it. Phase 12 adds the
-- missing half: existing rows are clinician-authored and take the default;
-- the only app path that writes `source='ai-extracted'` is the definer
-- function below, which always pairs it with 'clinician-verified' because the
-- values it persists were confirmed by the clinician (§11, §23).
alter table public.medications
  add column if not exists verification text
  check (verification in ('clinician-verified', 'ai-extracted'));

update public.medications set verification = 'clinician-verified' where verification is null;

alter table public.medications
  alter column verification set default 'clinician-verified',
  alter column verification set not null;

-- The one DB-owned write for extracted medications (the grant stays
-- doctor-only for ordinary authoring; `source`/`verification` are never
-- app-writable columns). The caller must be provider_doctor in the patient's
-- org — the database decides, exactly as everywhere else (§12). The 0007
-- BEFORE INSERT history trigger still fires on this path, so the `started`
-- lifecycle event and the timeline projection are unchanged.
create function public.record_extracted_medication(
  p_org_id uuid,
  p_patient_id uuid,
  p_name text,
  p_dose_amount numeric,
  p_dose_unit text,
  p_frequency text,
  p_route text,
  p_started_at timestamptz
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_medication_id uuid;
begin
  if coalesce(private.user_org_role(p_org_id), '') <> 'provider_doctor' then
    raise exception 'extracted_medication_forbidden';
  end if;
  if not exists (select 1 from public.patients p where p.id = p_patient_id and p.org_id = p_org_id) then
    raise exception 'extracted_medication_patient_mismatch';
  end if;

  insert into public.medications (
    org_id, patient_id, name, dose_amount, dose_unit, frequency, route, started_at,
    source, verification
  )
  values (
    p_org_id, p_patient_id, p_name, p_dose_amount, p_dose_unit, p_frequency, p_route,
    coalesce(p_started_at, now()),
    'ai-extracted', 'clinician-verified'
  )
  returning id into v_medication_id;

  return v_medication_id;
end;
$$;

revoke all on function public.record_extracted_medication(uuid, uuid, text, numeric, text, text, text, timestamptz) from public;
grant execute on function public.record_extracted_medication(uuid, uuid, text, numeric, text, text, text, timestamptz) to public;

-- ── RLS + grants. ─────────────────────────────────────────────────────────
alter table public.ocr_extractions enable row level security;

revoke all on public.ocr_extractions from public;
grant select on public.ocr_extractions to public;
grant insert (org_id, patient_id, document_id) on public.ocr_extractions to public;
grant update (status, payload, provider, rejection_reason) on public.ocr_extractions to public;
-- No DELETE grant, no DELETE policy.

-- SELECT: all four staff roles (an extraction in flight is team work).
create policy "select ocr extractions as staff"
on public.ocr_extractions for select to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'));

-- Writes: provider_doctor only (the ingestion clinician), in policy AND guard.
create policy "insert ocr extractions as author"
on public.ocr_extractions for insert to public
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

create policy "update ocr extractions as author"
on public.ocr_extractions for update to public
using ((select private.user_org_role(org_id)) = 'provider_doctor')
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

-- Audit (0003 pattern): upload, extraction, verification and rejection are
-- all attributable.
create function private.audit_ocr_extractions_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'ocr_extractions', new.id, new.org_id,
            jsonb_build_object('document_id', new.document_id, 'status', new.status));
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'ocr_extractions', new.id, new.org_id,
            jsonb_build_object(
              'status', jsonb_build_object('before', old.status, 'after', new.status),
              'verified_by', new.verified_by,
              'rejection_reason', new.rejection_reason));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'ocr_extractions', old.id, old.org_id,
            jsonb_build_object('status', old.status));
    return old;
  end if;
end;
$$;

create trigger audit_ocr_extractions after insert or update or delete on public.ocr_extractions
for each row execute function private.audit_ocr_extractions_change();


-- ── source: supabase/migrations/0012_patient_observations.sql ──
-- Migration 0012: patient-generated observations (phase 13).
-- Binds PRODUCT-MASTER-SPEC.md §14 (patient experience), §12, and PTH-01..03.
--
-- The patient's ONLY authoring surface in the whole product (PTH-02): a
-- closed vocabulary of measurements (weight, blood_pressure, glucose,
-- temperature, pulse) plus a note. A logged observation is append-only — no
-- UPDATE or DELETE grant exists — and the INSERT path re-derives the patient
-- from the VERIFIED SESSION, so a patient can only ever write their own row
-- and a client can never point `patient_id` at someone else (AUTH-07).
--
-- SELECT: the patient themself plus the four staff roles (a logged glucose
-- reading is clinically relevant to the care team). The provider-workspace
-- surfacing rides Phase 14 (TASK-02); the read path is safe today.
--
-- Patterns composed: 0003 audit; 0005 org/patient integrity + activity bump;
-- 0009 session attribution. `session_replication_role` is never set here.

create table public.patient_observations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  -- The recorder, taken from public.app_uid() by the guard (never the payload).
  user_id uuid not null references neon_auth."user"(id) on delete cascade,
  kind text not null check (kind in ('weight', 'blood_pressure', 'glucose', 'temperature', 'pulse', 'note')),
  -- The measured value; blood_pressure uses value_numeric (systolic) +
  -- value_secondary (diastolic). A note carries neither.
  value_numeric numeric(10, 3),
  value_secondary numeric(10, 3),
  unit text check (unit is null or unit in ('kg', 'g', 'lb', 'mmol/L', 'mg/dL', 'celsius', 'fahrenheit', 'bpm')),
  note text,
  -- When the PATIENT says it was taken, separate from created_at.
  observed_at timestamptz not null default now(),
  source text not null default 'patient'
    check (source in ('patient', 'staff', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index patient_observations_org_patient_idx
  on public.patient_observations (org_id, patient_id, observed_at desc, id desc);

-- Provenance ownership on insert (0009 touch pattern's INSERT half).
create function private.touch_observation_provenance() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.created_by := coalesce(public.app_uid(), new.created_by);
  new.user_id := coalesce(public.app_uid(), new.user_id);
  new.created_at := now();
  return new;
end;
$$;

create trigger touch_patient_observations_provenance before insert on public.patient_observations
for each row execute function private.touch_observation_provenance();

-- The self-scoping guard: the patient row must exist in this org AND belong to
-- the public user, the caller's role must be `patient`, and a
-- measurement kind must carry a value while a note may carry only text.
create function private.guard_patient_observation() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient record;
begin
  select id, org_id, user_id into v_patient from public.patients where id = new.patient_id;
  if v_patient.id is null then
    raise exception 'observation_patient_missing';
  end if;
  if v_patient.org_id <> new.org_id then
    raise exception 'observation_patient_mismatch';
  end if;
  -- The record's own user link is the authority, never the payload.
  if v_patient.user_id is null or v_patient.user_id <> public.app_uid() then
    raise exception 'observation_not_your_record';
  end if;
  if coalesce(private.user_org_role(new.org_id), '') <> 'patient' then
    raise exception 'observation_patient_role_required';
  end if;
  new.source := 'patient';

  if new.kind = 'note' then
    if new.value_numeric is not null or new.value_secondary is not null then
      raise exception 'observation_note_has_no_value';
    end if;
    if coalesce(new.note, '') = '' then
      raise exception 'observation_note_empty';
    end if;
  else
    if new.kind = 'blood_pressure' then
      if new.value_numeric is null or new.value_secondary is null then
        raise exception 'observation_blood_pressure_incomplete';
      end if;
    elsif new.value_numeric is null then
      raise exception 'observation_value_required';
    end if;
  end if;

  return new;
end;
$$;

create trigger guard_patient_observation before insert on public.patient_observations
for each row execute function private.guard_patient_observation();

-- Activity follows the patient (a logged reading is care activity).
create trigger activity_patient_observations after insert on public.patient_observations
for each row execute function private.clinical_patient_activity();

-- RLS + grants.
alter table public.patient_observations enable row level security;

revoke all on public.patient_observations from public;
grant select on public.patient_observations to public;
grant insert (org_id, patient_id, kind, value_numeric, value_secondary, unit, note, observed_at)
  on public.patient_observations to public;
-- No UPDATE, no DELETE: a logged observation is a record, not a draft.

-- SELECT: the patient themself, or staff in the org.
create policy "select observations as self-or-staff"
on public.patient_observations for select to public
using (
  user_id = (select public.app_uid())
  or (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
);

-- INSERT: the patient themself, with their role — enforced again by the guard.
create policy "insert observations as the patient"
on public.patient_observations for insert to public
with check (
  user_id = (select public.app_uid())
  and (select private.user_org_role(org_id)) = 'patient'
);

-- ── Patient self-read on their own clinical rows (PTH-01) ──────────────────
-- The Patient Home shows the same clinical facts the provider workspace shows
-- for this patient (medications, appointments, recent results, documents), so
-- the SELECT policies gain the SAME self-or-staff shape 0005 already uses on
-- `patients`: staff by org role, or the patient themself via the record's
-- `user_id` link. The write side is untouched — a patient never gains INSERT
-- or UPDATE on a clinical table; observations (above) remain their only
-- authoring surface (PTH-02, AUTH-07).
--
-- The join is through `patients` so the record's own user link is the
-- authority; `user_id` is never read from the request payload.
create or replace function private.can_read_own_patient_row(p_patient_id uuid)
returns boolean
language sql
security definer
set search_path = ''
stable
as $$
  select exists (
    select 1 from public.patients p
    where p.id = p_patient_id and p.user_id = public.app_uid()
  );
$$;

revoke all on function private.can_read_own_patient_row(uuid) from public;

do $$
declare
  t text;
begin
  foreach t in array array['medications', 'visits', 'lab_results', 'documents']
  loop
    execute format($f$
      create policy "select %1$s as self-or-staff" on public.%1$I
      for select to public
      using (
        (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
        or private.can_read_own_patient_row(patient_id)
      )
    $f$, t);
  end loop;
end;
$$;

-- ── Audit (0003 pattern): a patient-generated clinical-adjacent record is
-- attributable.
create function private.audit_patient_observations_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'patient_observations', new.id, new.org_id,
            jsonb_build_object('kind', new.kind, 'value', new.value_numeric));
    return new;
  end if;
  return null;
end;
$$;

create trigger audit_patient_observations after insert on public.patient_observations
for each row execute function private.audit_patient_observations_change();


-- ── source: supabase/migrations/0013_care_tasks.sql ──
-- Migration 0013: care tasks + the append-only completion log (phase 14).
-- Binds PRODUCT-MASTER-SPEC.md §14 (subtle care-task tracking + adherence),
-- §12, and TASK-01..03.
--
-- The honest shape for adherence: a task is ASSIGNABLE (provider_doctor only),
-- and a completion is an APPEND-ONLY EVENT with an actor and a timestamp —
-- never a mutable checkbox someone can flip without a trace. No UPDATE or
-- DELETE grant exists on the completion table; the log IS the adherence
-- story ("Logged 3 times · last on 12 Oct"), and nothing stores a score.
--
-- The completion INSERT path mirrors 0012 exactly: patient-self-only, with the
-- row's patient re-derived from `public.app_uid()` by the guard — the payload can
-- never name another patient (AUTH-07).
--
-- Patterns composed: 0003 audit; 0005 org/patient integrity + activity bump;
-- 0012 session-derived self-scoping. `session_replication_role` is never set.

create table public.care_tasks (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  title text not null,
  detail text,
  kind text not null default 'other'
    check (kind in ('measurement', 'medication', 'appointment', 'follow-up', 'other')),
  due_at timestamptz,
  status text not null default 'active' check (status in ('active', 'archived')),
  source text not null default 'clinician'
    check (source in ('clinician', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index care_tasks_org_patient_idx on public.care_tasks (org_id, patient_id, due_at, id desc);
create index care_tasks_org_status_idx on public.care_tasks (org_id, patient_id, status);

create table public.care_task_completions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  task_id uuid not null references public.care_tasks(id) on delete cascade,
  user_id uuid not null references neon_auth."user"(id) on delete cascade,
  note text,
  -- When the PATIENT says it happened, separate from created_at.
  completed_at timestamptz not null default now(),
  source text not null default 'patient' check (source in ('patient', 'staff', 'ai-extracted', 'imported')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index care_task_completions_org_task_idx
  on public.care_task_completions (org_id, task_id, completed_at desc, id desc);
create index care_task_completions_org_patient_idx
  on public.care_task_completions (org_id, patient_id, completed_at desc, id desc);

-- Provenance ownership (0012's touch pattern; tasks also update).
create function private.touch_clinical_provenance_013() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_table_name = 'care_tasks' then
    if tg_op = 'INSERT' then
      new.created_by := coalesce(public.app_uid(), new.created_by);
      new.updated_by := coalesce(public.app_uid(), new.updated_by, new.created_by);
      new.created_at := now();
    else
      new.updated_by := coalesce(public.app_uid(), new.updated_by);
    end if;
    new.updated_at := now();
  else
    -- care_task_completions is append-only: no updated_at exists.
    new.created_by := coalesce(public.app_uid(), new.created_by);
    new.user_id := coalesce(public.app_uid(), new.user_id);
    new.created_at := now();
  end if;
  return new;
end;
$$;

create trigger touch_care_tasks_provenance before insert or update on public.care_tasks
for each row execute function private.touch_clinical_provenance_013();

create trigger touch_care_task_completions_provenance before insert on public.care_task_completions
for each row execute function private.touch_clinical_provenance_013();

-- Authoring guard: doctor-only writes on the task; org/patient integrity.
create function private.guard_care_task() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then raise exception 'care_task_patient_missing'; end if;
  if v_patient_org <> new.org_id then raise exception 'care_task_patient_mismatch'; end if;
  if coalesce(private.user_org_role(new.org_id), '') <> 'provider_doctor' then
    raise exception 'care_task_clinical_forbidden';
  end if;
  return new;
end;
$$;

create trigger guard_care_task before insert or update on public.care_tasks
for each row execute function private.guard_care_task();

-- Completion guard: the patient themself, their own task, same org, and the
-- task must still be active. Staff INSERT is refused (a documented Phase-14
-- decision: completions are the patient's own record).
create function private.guard_care_task_completion() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient record;
  v_task record;
begin
  select org_id, user_id into v_patient from public.patients where id = new.patient_id;
  if v_patient.org_id is null then
    raise exception 'completion_patient_missing';
  end if;
  if v_patient.org_id <> new.org_id then
    raise exception 'completion_patient_mismatch';
  end if;
  if v_patient.user_id is null or v_patient.user_id <> public.app_uid() then
    raise exception 'completion_not_your_record';
  end if;
  if coalesce(private.user_org_role(new.org_id), '') <> 'patient' then
    raise exception 'completion_patient_role_required';
  end if;

  select org_id, patient_id, status into v_task from public.care_tasks where id = new.task_id;
  if v_task.org_id is null then
    raise exception 'completion_task_missing';
  end if;
  if v_task.org_id <> new.org_id or v_task.patient_id <> new.patient_id then
    raise exception 'completion_task_mismatch';
  end if;
  if v_task.status <> 'active' then
    raise exception 'completion_task_not_active';
  end if;

  new.source := 'patient';
  return new;
end;
$$;

create trigger guard_care_task_completion before insert on public.care_task_completions
for each row execute function private.guard_care_task_completion();

-- Activity follows the patient for both tables (a task assigned or completed
-- is care activity, and the folder's "last activity" should say so).
create trigger activity_care_tasks after insert or update on public.care_tasks
for each row execute function private.clinical_patient_activity();
create trigger activity_care_task_completions after insert on public.care_task_completions
for each row execute function private.clinical_patient_activity();

-- RLS + grants.
alter table public.care_tasks enable row level security;
alter table public.care_task_completions enable row level security;

revoke all on public.care_tasks from public;
grant select on public.care_tasks to public;
grant insert (org_id, patient_id, title, detail, kind, due_at, status) on public.care_tasks to public;
grant update (title, detail, kind, due_at, status) on public.care_tasks to public;
-- no delete grant: an archived task keeps its history.

revoke all on public.care_task_completions from public;
grant select on public.care_task_completions to public;
grant insert (org_id, patient_id, task_id, note, completed_at) on public.care_task_completions to public;
-- NO update, NO delete: the log is append-only.

-- SELECT: staff in the org, or the patient themself (both tables).
create policy "select care tasks as self-or-staff"
on public.care_tasks for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or private.can_read_own_patient_row(patient_id)
);

create policy "select care task completions as self-or-staff"
on public.care_task_completions for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or user_id = (select public.app_uid())
);

-- INSERT/UPDATE on tasks: provider_doctor only (policy + guard).
create policy "insert care tasks as author"
on public.care_tasks for insert to public
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

create policy "update care tasks as author"
on public.care_tasks for update to public
using ((select private.user_org_role(org_id)) = 'provider_doctor')
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

-- INSERT on completions: the patient themself (policy + guard).
create policy "insert completions as the patient"
on public.care_task_completions for insert to public
with check (
  user_id = (select public.app_uid())
  and (select private.user_org_role(org_id)) = 'patient'
);

-- Audit (0003 pattern): assignment, archive and every completion.
create function private.audit_care_tasks_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'care_tasks', new.id, new.org_id,
            jsonb_build_object('title', new.title, 'kind', new.kind, 'due_at', new.due_at));
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'care_tasks', new.id, new.org_id,
            jsonb_build_object(
              'status', jsonb_build_object('before', old.status, 'after', new.status),
              'title', jsonb_build_object('before', old.title, 'after', new.title)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'care_tasks', old.id, old.org_id,
            jsonb_build_object('title', old.title));
    return old;
  end if;
end;
$$;

create trigger audit_care_tasks after insert or update or delete on public.care_tasks
for each row execute function private.audit_care_tasks_change();

create function private.audit_care_task_completions_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'care_task_completions', new.id, new.org_id,
            jsonb_build_object('task_id', new.task_id, 'completed_at', new.completed_at));
    return new;
  end if;
  return null;
end;
$$;

create trigger audit_care_task_completions after insert on public.care_task_completions
for each row execute function private.audit_care_task_completions_change();


-- ── source: supabase/migrations/0014_conversations.sql ──
-- Migration 0014: the unified conversation model (phase 15).
-- Binds PRODUCT-MASTER-SPEC.md §15 (communication), §12, and COMM-01..03.
--
-- ONE abstraction for every channel (COMM-01): a conversation per patient per
-- organization, and an append-only message log whose `channel` column is the
-- Phase-16 seam — a WhatsApp or Telegram adapter writes the SAME rows with a
-- different channel and no UI change.
--
-- COMM-02 is structural, not copy: the model has NO clinical fields. A
-- message is a body between a care team and a patient; there is nowhere to put
-- a diagnosis, a dose or a result, so messaging cannot become a shadow medical
-- record. Messages are never projected onto the clinical timeline (§8.2).
--
-- The sender is ALWAYS re-derived from the session inside the guards: a staff
-- message requires sender_user_id = public.app_uid(), a patient message requires the
-- conversation's patient to belong to the public user. A payload can
-- never claim a different sender.
--
-- Patterns composed: 0003 audit; 0005 org/patient integrity; 0012 session
-- self-scoping. `session_replication_role` is never set here.

create table public.conversations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  status text not null default 'open' check (status in ('open', 'closed')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- One open conversation per patient: a closed thread can be superseded, but a
-- patient never has two live threads (the race-safe invariant the find-or-
-- create path depends on).
create unique index conversations_one_open_per_patient
  on public.conversations (patient_id) where status = 'open';
create index conversations_org_idx on public.conversations (org_id, updated_at desc, id desc);

create table public.conversation_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  -- org_id/patient_id are DENORMALISED COPIES of the conversation's, owned by
  -- the guard trigger: the app writes neither, and the guard refuses the row
  -- when the conversation cannot supply them (so they are always present on
  -- any successfully-inserted message).
  org_id uuid references public.organizations(id) on delete cascade,
  patient_id uuid references public.patients(id) on delete cascade,
  -- Re-derived from the session by the guard (never the payload).
  sender_kind text not null check (sender_kind in ('staff', 'patient', 'system')),
  sender_user_id uuid references neon_auth."user"(id) on delete set null,
  -- The Phase-16 seam: today's UI is in_app only.
  channel text not null default 'in_app' check (channel in ('in_app', 'whatsapp', 'telegram')),
  body text not null check (length(btrim(body)) > 0),
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index conversation_messages_conv_idx
  on public.conversation_messages (conversation_id, created_at, id);
create index conversation_messages_org_patient_idx
  on public.conversation_messages (org_id, patient_id, created_at desc, id desc);

-- Provenance ownership (0009 touch pattern).
create trigger touch_conversations_provenance before insert or update on public.conversations
for each row execute function private.touch_clinical_provenance();

-- Conversation guard: patient/org integrity; a NEW conversation is staff's
-- to open (CAN_MESSAGE: provider_doctor + nurse); the status transition table
-- is the only mutable surface.
create function private.guard_conversation() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then raise exception 'conversation_patient_missing'; end if;
  if v_patient_org <> new.org_id then raise exception 'conversation_patient_mismatch'; end if;

  if tg_op = 'INSERT' then
    if coalesce(private.user_org_role(new.org_id), '') not in ('provider_doctor', 'nurse') then
      raise exception 'conversation_create_forbidden';
    end if;
    new.status := 'open';
  else
    -- Only the status is mutable; identity is fixed at creation.
    if new.patient_id <> old.patient_id or new.org_id <> old.org_id then
      raise exception 'conversation_target_immutable';
    end if;
    if coalesce(private.user_org_role(new.org_id), '') not in ('provider_doctor', 'nurse') then
      raise exception 'conversation_close_forbidden';
    end if;
    if old.status = 'closed' then
      raise exception 'conversation_closed_final';
    end if;
    if new.status <> 'closed' then
      raise exception 'conversation_bad_transition';
    end if;
  end if;
  return new;
end;
$$;

create trigger guard_conversation before insert or update on public.conversations
for each row execute function private.guard_conversation();

-- Message guard: the sender is re-derived from the session, the message's
-- org/patient must match its conversation, and nobody may edit or delete a
-- message (append-only: no UPDATE trigger is installed at all).
create function private.guard_conversation_message() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_conversation record;
  v_patient record;
begin
  select org_id, patient_id, status into v_conversation
  from public.conversations where id = new.conversation_id;
  if v_conversation.org_id is null then
    raise exception 'message_conversation_missing';
  end if;
  new.org_id := v_conversation.org_id;
  new.patient_id := v_conversation.patient_id;
  if v_conversation.status <> 'open' then
    raise exception 'message_conversation_closed';
  end if;

  new.body := btrim(new.body);
  new.created_by := public.app_uid();

  if coalesce(private.user_org_role(new.org_id), '') in ('provider_doctor', 'nurse') then
    -- Staff sender: identity from the session, never the payload.
    new.sender_kind := 'staff';
    new.sender_user_id := public.app_uid();
  else
    -- Patient sender: the conversation's patient must belong to this user.
    select user_id into v_patient from public.patients where id = new.patient_id;
    if coalesce(private.user_org_role(new.org_id), '') <> 'patient'
      or v_patient.user_id is null
      or v_patient.user_id <> public.app_uid()
    then
      raise exception 'message_sender_forbidden';
    end if;
    new.sender_kind := 'patient';
    new.sender_user_id := public.app_uid();
  end if;
  return new;
end;
$$;

create trigger guard_conversation_message before insert on public.conversation_messages
for each row execute function private.guard_conversation_message();

-- The conversation's updated_at follows its messages (the log is the activity).
create function private.touch_conversation_on_message() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.conversations set updated_at = now()
  where id = new.conversation_id;
  return new;
end;
$$;

create trigger touch_conversation_on_message after insert on public.conversation_messages
for each row execute function private.touch_conversation_on_message();

-- RLS + grants.
alter table public.conversations enable row level security;
alter table public.conversation_messages enable row level security;

revoke all on public.conversations from public;
grant select on public.conversations to public;
grant insert (org_id, patient_id) on public.conversations to public;
grant update (status) on public.conversations to public;
-- no delete grant.

revoke all on public.conversation_messages from public;
grant select on public.conversation_messages to public;
grant insert (conversation_id, body, channel) on public.conversation_messages to public;
-- NO update, NO delete: the log is append-only.
-- SELECT: the org's staff, or the conversation's own patient.
create policy "select conversations as self-or-staff"
on public.conversations for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or private.can_read_own_patient_row(patient_id)
);

create policy "select conversation messages as self-or-staff"
on public.conversation_messages for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or private.can_read_own_patient_row(patient_id)
);

-- WRITE: doctor + nurse (the guard narrows further), policy + guard.
create policy "insert conversations as care team"
on public.conversations for insert to public
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'));

create policy "update conversations as care team"
on public.conversations for update to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'))
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'));

create policy "insert conversation messages as participant"
on public.conversation_messages for insert to public
with check (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse')
  or private.can_read_own_patient_row(patient_id)
);

-- Audit (0003 pattern): opening, closing and every message.
create function private.audit_conversations_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'conversations', new.id, new.org_id,
            jsonb_build_object('patient_id', new.patient_id, 'status', new.status));
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'conversations', new.id, new.org_id,
            jsonb_build_object('status', jsonb_build_object('before', old.status, 'after', new.status)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'conversations', old.id, old.org_id, null);
    return old;
  end if;
end;
$$;

create trigger audit_conversations after insert or update or delete on public.conversations
for each row execute function private.audit_conversations_change();

create function private.audit_conversation_messages_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
  values (coalesce(public.app_uid(), new.created_by), 'INSERT', 'conversation_messages', new.id, new.org_id,
          jsonb_build_object('conversation_id', new.conversation_id, 'sender_kind', new.sender_kind,
                             'channel', new.channel));
  return new;
end;
$$;

create trigger audit_conversation_messages after insert on public.conversation_messages
for each row execute function private.audit_conversation_messages_change();


-- ── source: supabase/migrations/0015_channels.sql ──
-- Migration 0015: channel endpoints, adapters' record and delivery log
-- (phase 16). Binds PRODUCT-MASTER-SPEC.md §15 (channel adapters), §12, and
-- CHAN-01..03.
--
-- The channel layer sits UNDER the unified conversation (0014): a notification
-- is never free-floating — every delivery row points at the conversation
-- message that caused it, so a WhatsApp or Telegram message can only exist
-- because a message in the thread exists (CHAN-03: the attribution is
-- structural, not a convention).
--
-- `channel_endpoints` holds the patient's reachable handles, managed by staff
-- (contact data, not a patient write surface). `notification_deliveries` is
-- append-only: the delivery log is the truth about what left the building,
-- including the honest `not_configured` state — a simulated success is
-- forbidden (§27).
--
-- Patterns composed: 0003 audit; 0005 org/patient integrity; 0012 session
-- self-scoping; 0014 conversation FK. `session_replication_role` is never set.

create table public.channel_endpoints (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  channel text not null check (channel in ('in_app', 'whatsapp', 'telegram')),
  -- The external handle: an E.164 phone number for WhatsApp, a chat id for
  -- Telegram. Recorded by staff; the adapter never guesses a destination.
  handle text not null check (length(btrim(handle)) > 0),
  status text not null default 'active' check (status in ('active', 'inactive')),
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index channel_endpoints_unique
  on public.channel_endpoints (patient_id, channel, handle);
create index channel_endpoints_org_patient_idx
  on public.channel_endpoints (org_id, patient_id, status);

create table public.notification_deliveries (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  message_id uuid not null references public.conversation_messages(id) on delete cascade,
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  channel text not null check (channel in ('whatsapp', 'telegram')),
  handle text not null,
  -- delivered | not_configured | failed — the honest state, never a fake one.
  status text not null check (status in ('delivered', 'not_configured', 'failed')),
  -- The provider's own reference for a delivered message (auditability).
  provider_reference text,
  reason text,
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index notification_deliveries_message_idx
  on public.notification_deliveries (message_id, created_at, id);
create index notification_deliveries_org_patient_idx
  on public.notification_deliveries (org_id, patient_id, created_at desc, id desc);

-- Provenance ownership (0009 touch pattern); endpoints update, deliveries
-- never do.
create trigger touch_channel_endpoints_provenance before insert or update on public.channel_endpoints
for each row execute function private.touch_clinical_provenance();

create function private.touch_notification_delivery() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.created_by := coalesce(public.app_uid(), new.created_by);
  new.created_at := now();
  return new;
end;
$$;

create trigger touch_notification_deliveries_provenance before insert on public.notification_deliveries
for each row execute function private.touch_notification_delivery();

-- Endpoints guard: patient/org integrity; staff (doctor + nurse) only.
create function private.guard_channel_endpoint() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then raise exception 'endpoint_patient_missing'; end if;
  if v_patient_org <> new.org_id then raise exception 'endpoint_patient_mismatch'; end if;
  if coalesce(private.user_org_role(new.org_id), '') not in ('provider_doctor', 'nurse') then
    raise exception 'endpoint_manage_forbidden';
  end if;
  return new;
end;
$$;

create trigger guard_channel_endpoint before insert or update on public.channel_endpoints
for each row execute function private.guard_channel_endpoint();

-- Deliveries guard: append-only and attributed. The message must belong to the
-- same patient/org (no cross-patient sends), and the row is inserted only by
-- the server-side workflow — a patient can never write one.
create function private.guard_notification_delivery() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_message record;
begin
  if coalesce(private.user_org_role(new.org_id), '') not in ('provider_doctor', 'nurse') then
    raise exception 'delivery_write_forbidden';
  end if;

  select conversation_id, org_id, patient_id into v_message
  from public.conversation_messages where id = new.message_id;
  if v_message.conversation_id is null then
    raise exception 'delivery_message_missing';
  end if;
  if v_message.org_id <> new.org_id
    or v_message.patient_id <> new.patient_id
    or v_message.conversation_id <> new.conversation_id
  then
    raise exception 'delivery_message_mismatch';
  end if;

  -- The status vocabulary is enforced by the check; a delivered row must
  -- carry no failure reason, and a not_configured row must say why.
  if new.status = 'delivered' and new.reason is not null then
    raise exception 'delivery_delivered_has_reason';
  end if;
  if new.status in ('not_configured', 'failed') and coalesce(new.reason, '') = '' then
    raise exception 'delivery_reason_required';
  end if;
  return new;
end;
$$;

create trigger guard_notification_delivery before insert on public.notification_deliveries
for each row execute function private.guard_notification_delivery();

-- RLS + grants.
alter table public.channel_endpoints enable row level security;
alter table public.notification_deliveries enable row level security;

revoke all on public.channel_endpoints from public;
grant select on public.channel_endpoints to public;
grant insert (org_id, patient_id, channel, handle) on public.channel_endpoints to public;
grant update (handle, status) on public.channel_endpoints to public;
-- no delete grant.

revoke all on public.notification_deliveries from public;
grant select on public.notification_deliveries to public;
grant insert (conversation_id, message_id, org_id, patient_id, channel, handle, status, provider_reference, reason)
  on public.notification_deliveries to public;
-- NO update, NO delete: the delivery log is append-only.

-- SELECT: the org's staff (endpoints and deliveries are operational records).
create policy "select channel endpoints as staff"
on public.channel_endpoints for select to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'));

create policy "select notification deliveries as staff"
on public.notification_deliveries for select to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner'));

-- WRITE: doctor + nurse (the guard narrows further), policy + guard.
create policy "insert channel endpoints as care team"
on public.channel_endpoints for insert to public
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'));

create policy "update channel endpoints as care team"
on public.channel_endpoints for update to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'))
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'));

create policy "insert notification deliveries as care team"
on public.notification_deliveries for insert to public
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'nurse'));

-- Audit (0003 pattern).
create function private.audit_channel_endpoints_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'channel_endpoints', new.id, new.org_id,
            jsonb_build_object('channel', new.channel, 'status', new.status));
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'channel_endpoints', new.id, new.org_id,
            jsonb_build_object('status', jsonb_build_object('before', old.status, 'after', new.status)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'channel_endpoints', old.id, old.org_id,
            jsonb_build_object('channel', old.channel));
    return old;
  end if;
end;
$$;

create trigger audit_channel_endpoints after insert or update or delete on public.channel_endpoints
for each row execute function private.audit_channel_endpoints_change();

create function private.audit_notification_deliveries_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
  values (coalesce(public.app_uid(), new.created_by), 'INSERT', 'notification_deliveries', new.id, new.org_id,
          jsonb_build_object('channel', new.channel, 'status', new.status, 'message_id', new.message_id));
  return new;
end;
$$;

create trigger audit_notification_deliveries after insert on public.notification_deliveries
for each row execute function private.audit_notification_deliveries_change();


-- ── source: supabase/migrations/0016_telehealth.sql ──
-- Migration 0016: telehealth sessions (phase 17). Binds
-- PRODUCT-MASTER-SPEC.md §13 (the Encounter/Visit chain), §3.1/§12
-- (authorization enforced server-side), §27 (nothing simulated), and the
-- TH-01..03 requirements.
--
-- A telehealth session is the consultation ROOM for a visit that already is
-- the appointment: the row points at the visit (never re-declaring the
-- patient/org), carries the rejoin reference, and records the transport
-- honestly — `not_configured` until the owner connects a provider (§27: a
-- simulated connection is forbidden, the Phase-12 no-provider precedent and
-- Phase-16's adapter discipline).
--
-- Patterns composed, copied not reinvented:
--   0003  audit trigger-per-table.
--   0005  trigger-owned provenance; private.user_org_role as the ONLY
--         membership reader; revoke-then-regrant; column-level grants; no
--         delete policy and no delete grant.
--   0006  the visit's clinical guard role list (provider_doctor) and the
--         org/patient integrity check.
--   0014  self-or-staff SELECT via private.can_read_own_patient_row.
--
-- Trigger-owned: created_by/updated_by/created_at/updated_at. `session_replication_role`
-- is never set.

create table public.telehealth_sessions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  -- The appointment: a session cannot exist without its visit, and the
  -- visit's own model stays the encounter of record (TH-03).
  visit_id uuid not null references public.visits(id) on delete cascade,
  -- The closed status vocabulary, mirrored byte-for-byte by
  -- src/lib/telehealth/status.ts.
  status text not null default 'scheduled'
    check (status in ('scheduled', 'in_progress', 'completed', 'cancelled')),
  -- The opaque rejoin reference. The join surface shows this and nothing else
  -- about the session's identity.
  join_token text not null unique default encode(gen_random_bytes(24), 'hex'),
  -- The transport: honest until a provider is connected (no video SDK ships
  -- simulated, §27).
  transport text not null default 'not_configured'
    check (transport in ('not_configured', 'connected')),
  transport_reference text,
  cancellation_reason text,
  started_at timestamptz,
  ended_at timestamptz,
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- One ACTIVE session per visit: a second consultation on the same
-- appointment is refused by the index, not queued.
create unique index telehealth_sessions_active_visit_uq
  on public.telehealth_sessions (visit_id)
  where status in ('scheduled', 'in_progress');
create index telehealth_sessions_org_status_idx
  on public.telehealth_sessions (org_id, status, created_at desc, id desc);
create index telehealth_sessions_patient_idx
  on public.telehealth_sessions (patient_id, created_at desc, id desc);

create trigger touch_telehealth_sessions_provenance
before insert or update on public.telehealth_sessions
for each row execute function private.touch_clinical_provenance();

-- The session guard: the visit must exist and carry the same org/patient
-- (no cross-patient consultation), only clinical authors write, and the
-- closed status vocabulary can only move forward — a skip, a repeat or a
-- backward move is refused, and the timestamps follow the transition.
create function private.guard_telehealth_session() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_visit record;
begin
  select org_id, patient_id into v_visit from public.visits where id = new.visit_id;
  if v_visit.org_id is null then
    raise exception 'session_visit_missing';
  end if;
  if v_visit.org_id <> new.org_id or v_visit.patient_id <> new.patient_id then
    raise exception 'session_visit_mismatch';
  end if;

  if coalesce(private.user_org_role(new.org_id), '') <> 'provider_doctor' then
    raise exception 'session_write_forbidden';
  end if;

  if tg_op = 'INSERT' then
    -- A session is born scheduled; the transport starts unconfigured.
    if new.status <> 'scheduled' then
      raise exception 'session_bad_open_status';
    end if;
    if new.started_at is not null or new.ended_at is not null then
      raise exception 'session_bad_timestamps';
    end if;
    return new;
  end if;

  -- UPDATE: the transition discipline.
  if new.status is distinct from old.status then
    if old.status = 'scheduled' and new.status = 'in_progress' then
      new.started_at := now();
      new.ended_at := null;
    elsif old.status = 'in_progress' and new.status = 'completed' then
      if new.started_at is null then new.started_at := now(); end if;
      new.ended_at := now();
    elsif old.status in ('scheduled', 'in_progress') and new.status = 'cancelled' then
      new.ended_at := now();
      if coalesce(btrim(new.cancellation_reason), '') = '' then
        raise exception 'session_cancel_reason_required';
      end if;
    else
      raise exception 'session_bad_transition';
    end if;
  else
    -- No status change: the timestamps are never hand-edited.
    if new.started_at is distinct from old.started_at
       or new.ended_at is distinct from old.ended_at then
      raise exception 'session_bad_timestamps';
    end if;
  end if;

  return new;
end;
$$;

create trigger guard_telehealth_session
before insert or update on public.telehealth_sessions
for each row execute function private.guard_telehealth_session();

-- RLS + grants.
alter table public.telehealth_sessions enable row level security;

revoke all on public.telehealth_sessions from public;
grant select on public.telehealth_sessions to public;
grant insert (org_id, patient_id, visit_id, status, transport, transport_reference, cancellation_reason)
  on public.telehealth_sessions to public;
grant update (status, transport, transport_reference, cancellation_reason)
  on public.telehealth_sessions to public;
-- no delete grant: a consultation is not a product delete action. started_at/
-- ended_at/join_token are trigger/constraint-owned and never app-written.

-- SELECT: the org's staff, or the patient themself (0014's self-or-staff).
create policy "select telehealth sessions as self-or-staff"
on public.telehealth_sessions for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or private.can_read_own_patient_row(patient_id)
);

-- WRITE: doctor only (policy + guard, 0006's clinical-author shape).
create policy "insert telehealth sessions as doctor"
on public.telehealth_sessions for insert to public
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

create policy "update telehealth sessions as doctor"
on public.telehealth_sessions for update to public
using ((select private.user_org_role(org_id)) = 'provider_doctor')
with check ((select private.user_org_role(org_id)) = 'provider_doctor');

-- Audit (0003 pattern).
create function private.audit_telehealth_sessions_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'telehealth_sessions', new.id, new.org_id,
            jsonb_build_object('visit_id', new.visit_id, 'status', new.status));
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'telehealth_sessions', new.id, new.org_id,
            jsonb_build_object('before', jsonb_build_object('status', old.status),
                               'after', jsonb_build_object('status', new.status)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'telehealth_sessions', old.id, old.org_id,
            jsonb_build_object('before', jsonb_build_object('status', old.status)));
    return old;
  end if;
end;
$$;

create trigger audit_telehealth_sessions after insert or update or delete
on public.telehealth_sessions for each row
execute function private.audit_telehealth_sessions_change();


-- ── source: supabase/migrations/0017_payments.sql ──
-- Migration 0017: invoices and payments (phase 18). Binds
-- PRODUCT-MASTER-SPEC.md §13 (the relational chain), §12 (authorization
-- enforced server-side), §23 (provenance), §27 (nothing simulated), and the
-- PAY-01..04 requirements.
--
-- The payment layer is deliberately OUTSIDE the clinical chain: the timeline
-- projection (0014-era) reads clinical events only, so no financial row can
-- ever surface on it (PAY-04). Amounts are integer MINOR UNITS — a float
-- money column is a bug farm, and cents are the only honest unit for a
-- ledger.
--
-- Patterns composed, copied not reinvented:
--   0003  audit trigger-per-table.
--   0005  trigger-owned provenance; private.user_org_role as the ONLY
--         membership reader; revoke-then-regrant; column-level grants; the
--         org/patient integrity guard; no delete grant on a ledger row.
--   0014  self-or-staff SELECT via private.can_read_own_patient_row.
--   0015/0016  the honest-status vocabulary discipline (a payment records
--         what actually happened, including "nothing was captured").
--
-- The payment PROVIDER sits behind the abstraction in
-- src/lib/payments/provider.ts (0016's adapter precedent): with no provider
-- connected, an attempt records `not_configured` and its reason — a simulated
-- settlement is forbidden (§27).
--
-- Trigger-owned: created_by/updated_by/created_at/updated_at.
-- `session_replication_role` is never set.

create table public.invoices (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  -- The consultation fee's appointment, when the invoice is for one.
  visit_id uuid references public.visits(id) on delete set null,
  -- Money: integer minor units + an ISO-4217 code. Never a float.
  amount_minor bigint not null check (amount_minor > 0),
  currency text not null default 'USD' check (currency ~ '^[A-Z]{3}$'),
  status text not null default 'draft'
    check (status in ('draft', 'issued', 'paid', 'void')),
  description text not null default '' check (length(btrim(description)) > 0),
  issued_at timestamptz,
  voided_at timestamptz,
  created_by uuid references neon_auth."user"(id) on delete set null,
  updated_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index invoices_org_status_idx on public.invoices (org_id, status, created_at desc, id desc);
create index invoices_patient_idx on public.invoices (patient_id, created_at desc, id desc);

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  patient_id uuid not null references public.patients(id) on delete cascade,
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  amount_minor bigint not null check (amount_minor > 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  -- settled | not_configured | failed — what actually happened (§27).
  status text not null check (status in ('settled', 'not_configured', 'failed')),
  provider_reference text,
  reason text,
  created_by uuid references neon_auth."user"(id) on delete set null,
  created_at timestamptz not null default now()
);

create index payments_invoice_idx on public.payments (invoice_id, created_at, id);
create index payments_org_idx on public.payments (org_id, created_at desc, id desc);

create trigger touch_invoices_provenance
before insert or update on public.invoices
for each row execute function private.touch_clinical_provenance();

create trigger touch_payments_provenance
before insert on public.payments
for each row execute function private.touch_clinical_provenance();

-- INVARIANT (004 pattern): the derived `paid` status. An invoice reads paid
-- when its settled payments cover the amount; issued_at/voided_at follow the
-- status transition and are never hand-edited. Enforced on write so no client
-- claim can survive.
create function private.guard_invoice() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_patient_org uuid;
  v_settled bigint;
begin
  select org_id into v_patient_org from public.patients where id = new.patient_id;
  if v_patient_org is null then
    raise exception 'invoice_patient_missing';
  end if;
  if v_patient_org <> new.org_id then
    raise exception 'invoice_patient_mismatch';
  end if;

  -- The optional visit must belong to the same org/patient (a consultation
  -- fee can never point at another patient's appointment).
  if new.visit_id is not null then
    if not exists (
      select 1 from public.visits
      where id = new.visit_id and org_id = new.org_id and patient_id = new.patient_id
    ) then
      raise exception 'invoice_visit_mismatch';
    end if;
  end if;

  if coalesce(private.user_org_role(new.org_id), '') not in ('provider_doctor', 'receptionist', 'admin_owner') then
    raise exception 'invoice_write_forbidden';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'invoice_bad_open_status';
    end if;
    if new.issued_at is not null or new.voided_at is not null then
      raise exception 'invoice_bad_timestamps';
    end if;
    return new;
  end if;

  -- UPDATE: transitions only, and the timestamps follow them.
  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'issued' then
      new.issued_at := now();
    elsif old.status = 'issued' and new.status = 'void' then
      new.voided_at := now();
    elsif old.status = 'issued' and new.status = 'paid' then
      -- paid is DERIVED: it is set only when the settled balance covers it.
      select coalesce(sum(amount_minor), 0) into v_settled
      from public.payments
      where invoice_id = new.id and status = 'settled';
      if v_settled < new.amount_minor then
        raise exception 'invoice_paid_not_covered';
      end if;
    else
      raise exception 'invoice_bad_transition';
    end if;
  else
    if new.issued_at is distinct from old.issued_at
       or new.voided_at is distinct from old.voided_at then
      raise exception 'invoice_bad_timestamps';
    end if;
  end if;

  return new;
end;
$$;

create trigger guard_invoice before insert or update on public.invoices
for each row execute function private.guard_invoice();

-- PAYMENT guard: append-only rows attributed to a LIVE (issued) invoice of
-- the same org/patient, the settled sum can never exceed the amount, and a
-- not_configured/failed row MUST say why.
create function private.guard_payment() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice record;
  v_settled bigint;
begin
  select org_id, patient_id, status, amount_minor into v_invoice
  from public.invoices where id = new.invoice_id;
  if v_invoice.org_id is null then
    raise exception 'payment_invoice_missing';
  end if;
  if v_invoice.org_id <> new.org_id or v_invoice.patient_id <> new.patient_id then
    raise exception 'payment_invoice_mismatch';
  end if;
  if v_invoice.status <> 'issued' then
    raise exception 'payment_invoice_not_live';
  end if;

  if coalesce(private.user_org_role(new.org_id), '') not in ('provider_doctor', 'receptionist', 'admin_owner') then
    raise exception 'payment_write_forbidden';
  end if;

  if new.status = 'settled' then
    if new.reason is not null then
      raise exception 'payment_settled_has_reason';
    end if;
    select coalesce(sum(amount_minor), 0) into v_settled
    from public.payments where invoice_id = new.invoice_id and status = 'settled';
    if v_settled + new.amount_minor > v_invoice.amount_minor then
      raise exception 'payment_overpay';
    end if;
  else
    if coalesce(btrim(new.reason), '') = '' then
      raise exception 'payment_reason_required';
    end if;
  end if;

  return new;
end;
$$;

create trigger guard_payment before insert on public.payments
for each row execute function private.guard_payment();

-- RLS + grants.
alter table public.invoices enable row level security;
alter table public.payments enable row level security;

revoke all on public.invoices from public;
grant select on public.invoices to public;
grant insert (org_id, patient_id, visit_id, amount_minor, currency, description)
  on public.invoices to public;
grant update (status, description) on public.invoices to public;
-- no delete grant.

revoke all on public.payments from public;
grant select on public.payments to public;
grant insert (org_id, patient_id, invoice_id, amount_minor, currency, status, provider_reference, reason)
  on public.payments to public;
-- NO update, NO delete: the payment log is append-only.

create policy "select invoices as self-or-staff"
on public.invoices for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or private.can_read_own_patient_row(patient_id)
);

create policy "insert invoices as billing staff"
on public.invoices for insert to public
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'receptionist', 'admin_owner'));

create policy "update invoices as billing staff"
on public.invoices for update to public
using ((select private.user_org_role(org_id)) in ('provider_doctor', 'receptionist', 'admin_owner'))
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'receptionist', 'admin_owner'));

create policy "select payments as self-or-staff"
on public.payments for select to public
using (
  (select private.user_org_role(org_id)) in ('provider_doctor', 'nurse', 'receptionist', 'admin_owner')
  or private.can_read_own_patient_row(patient_id)
);

create policy "insert payments as billing staff"
on public.payments for insert to public
with check ((select private.user_org_role(org_id)) in ('provider_doctor', 'receptionist', 'admin_owner'));

-- Audit (0003 pattern).
create function private.audit_invoices_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'invoices', new.id, new.org_id,
            jsonb_build_object('patient_id', new.patient_id, 'amount_minor', new.amount_minor,
                               'currency', new.currency, 'status', new.status));
    return new;
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.updated_by), tg_op, 'invoices', new.id, new.org_id,
            jsonb_build_object('before', jsonb_build_object('status', old.status),
                               'after', jsonb_build_object('status', new.status)));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), old.updated_by), tg_op, 'invoices', old.id, new.org_id,
            jsonb_build_object('before', jsonb_build_object('status', old.status)));
    return old;
  end if;
end;
$$;

create trigger audit_invoices after insert or update or delete
on public.invoices for each row execute function private.audit_invoices_change();

create function private.audit_payments_change() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'payments', new.id, new.org_id,
            jsonb_build_object('invoice_id', new.invoice_id, 'amount_minor', new.amount_minor,
                               'status', new.status));
    return new;
  else
    insert into public.audit_log (actor, action, entity, entity_id, org_id, diff)
    values (coalesce(public.app_uid(), new.created_by), tg_op, 'payments', new.id, old.org_id,
            jsonb_build_object('before', jsonb_build_object('status', old.status)));
    return old;
  end if;
end;
$$;

create trigger audit_payments after insert or delete
on public.payments for each row execute function private.audit_payments_change();


-- ── source: supabase/migrations/0018_security_hardening.sql ──
-- Migration 0018: security hardening amendments (phase 20, SEC-01/02).
--
-- Finding F-2 of the Phase-20 audit: the `patient-documents` bucket (0008)
-- granted SELECT and INSERT to STAFF only, so a patient could not retrieve
-- their OWN document objects (a prescription image they uploaded, a scanned
-- result). That is over-restriction, not a leak — but a patient reading
-- their own record is a requirement the storage policies silently denied.
--
-- The path convention `<org_id>/<patient_id>/<uuid>` (0008) makes the patient
-- the SECOND segment. The new policy compares it to the patient row whose
-- `user_id` is the public user, so media access and record access
-- finally agree. The comparison is TEXT (`p.id::text = split_part(...)`) on
-- purpose: a malformed object name fails the compare instead of raising a
-- cast error inside the policy.
--
-- No other table or policy changed in this phase: the audit's other findings
-- were resolved in application code (see 20-SECURITY-AUDIT.md), not here.

-- NEON-PORT: dropped Supabase storage policy (Neon Object Storage `uploads` bucket; enforced in app).



-- NEON-PORT: 27 app tables ported (18 sources).
-- RLS policies above are inert for the table owner; enforcement is app-layer
-- org filters (resolveWorkspaceRole) + trigger guards. See neon/README.md.
